window.NIGHTS.cases[9]={"nr":9,"id":"case09","title":"Die Straßen bluten Neon","subtitle":"","level":"Kriminelle Ebene","from":233,"to":258,"mythen":[],"sections":[{"id":"titel-und-pitch","kind":"intro","title":"Titel und Pitch","page":233,"layer":null,"blocks":13},{"id":"toxischer-krieg-zweier-paten","kind":"place","title":"TOXISCHER KRIEG ZWEIER PATEN","page":235,"layer":null,"blocks":9},{"id":"das-zentrale-dilemma-fuer-die-spieler-innen","kind":"place","title":"DAS ZENTRALE DILEMMA FÜR DIE SPIELER:INNEN","page":235,"layer":null,"blocks":9},{"id":"haeuserkampf-und-bandenkrieg","kind":"place","title":"HÄUSERKAMPF UND BANDENKRIEG","page":236,"layer":null,"blocks":8},{"id":"auseinandersetzung-mit-dem-koenig","kind":"place","title":"AUSEINANDERSETZUNG MIT DEM KÖNIG","page":236,"layer":null,"blocks":4},{"id":"der-preis-des-krieges","kind":"place","title":"DER PREIS DES KRIEGES","page":236,"layer":null,"blocks":4},{"id":"schicht-0-aufhaenger","kind":"layer","title":"SCHICHT 0: AUFHÄNGER","page":237,"layer":null,"blocks":30},{"id":"schicht-1-scharmuetzel-an-den-grenzen","kind":"layer","title":"SCHICHT 1: SCHARMÜTZEL AN DEN GRENZEN","page":239,"layer":null,"blocks":3},{"id":"die-grenzlande","kind":"place","title":"DIE GRENZLANDE","page":239,"layer":"schicht-1-scharmuetzel-an-den-grenzen","blocks":15},{"id":"einheiten-der-fraktionen","kind":"place","title":"EINHEITEN DER FRAKTIONEN","page":241,"layer":"schicht-1-scharmuetzel-an-den-grenzen","blocks":24},{"id":"blutbad-in-der-innenstadt","kind":"place","title":"BLUTBAD IN DER INNENSTADT","page":242,"layer":"schicht-1-scharmuetzel-an-den-grenzen","blocks":39},{"id":"der-steinaltar","kind":"place","title":"DER STEINALTAR","page":244,"layer":"schicht-1-scharmuetzel-an-den-grenzen","blocks":21},{"id":"camelot","kind":"place","title":"CAMELOT","page":246,"layer":"schicht-1-scharmuetzel-an-den-grenzen","blocks":18},{"id":"schicht-2-ausbruch-des-krieges","kind":"layer","title":"SCHICHT 2: AUSBRUCH DES KRIEGES","page":247,"layer":null,"blocks":4},{"id":"das-geheimnis-des-koenigs","kind":"place","title":"DAS GEHEIMNIS DES KÖNIGS","page":247,"layer":"schicht-2-ausbruch-des-krieges","blocks":13},{"id":"schlacht-an-der-calmann-bruecke","kind":"place","title":"SCHLACHT AN DER CALMANN-BRÜCKE","page":248,"layer":"schicht-2-ausbruch-des-krieges","blocks":18},{"id":"ray-gibbons-junggesellenbude","kind":"place","title":"RAY GIBBONS’ JUNGGESELLENBUDE","page":251,"layer":"schicht-2-ausbruch-des-krieges","blocks":27},{"id":"schicht-3-streben-nach-macht","kind":"layer","title":"SCHICHT 3: STREBEN NACH MACHT","page":253,"layer":null,"blocks":3},{"id":"ray-gibbons","kind":"place","title":"RAY GIBBONS","page":253,"layer":"schicht-3-streben-nach-macht","blocks":22},{"id":"risse-allueberall","kind":"place","title":"RISSE ALLÜBERALL","page":254,"layer":"schicht-3-streben-nach-macht","blocks":34},{"id":"schicht-4-nach-dem-krieg","kind":"layer","title":"SCHICHT 4: NACH DEM KRIEG","page":257,"layer":null,"blocks":5},{"id":"le-griffon-segr-ant","kind":"place","title":"LE GRIFFON SEGRÉANT","page":257,"layer":"schicht-4-nach-dem-krieg","blocks":17}],"pages":{"233":{"tab":"","blocks":[{"t":"sh","x":"<b>EIN OFFENER KRIEG ZWISCHEN RÜCKSICHTSLOSEN</b>","sz":20.0,"box":[122.1,776.1,473.2,796.1],"p":233,"i":0,"sec":"titel-und-pitch"}],"size":[595.276,841.89]},"234":{"tab":"","blocks":[{"t":"p","x":"Es ist eine unruhige Zeit. Ein Verbrechersyndikat aus dem verschlafenen Vorort Whitecliff hat mehrere Stadtteile übernommen und zu seinem „Königreich“ erklärt. Sein „König“, der mehrmals dem Tod entronnen ist, dehnt sein Gebiet aus, indem er einen brutalen Krieg gegen die anderen Banden der Stadt führt. Zumindest stellen das die Medien so dar. Die Öffentlichkeit weiß wenig über das Ausmaß der Kräfte, die aufeinanderprallen: Es ist ein Krieg der Monarchen, der Armeen, Ritter:innen und allmächtigen Zauber:innen. Selbst die Leute in den grauen Anzügen können dieses blutige Chaos nicht eindämmen. Werdet ihr es aufhalten, bevor es die Stadt in Stücke reißt?","sz":13.0,"box":[53.9,60.1,284.8,319.6],"p":234,"i":0,"sec":"titel-und-pitch"},{"t":"p","x":"<i>Die Straßen bluten Neon</i> ist als Finale eines Kriminaldramas konzipiert, in dem die Ambitionen eines kriminellen Imperiums zu einem stadtweiten Unterweltkrieg führen, der entweder in einem endgültigen Sieg oder im absoluten Untergang gipfelt. Der Fall verdeutlicht die Zerstörung, die der giftige Drang, einen Feind zu vernichten, anrichtet – ein vergebliches Unterfangen, das bestenfalls mit einem Pyrrhussieg endet. Was mit Revierkämpfen und Bandenkrieg beginnt, entwickelt sich zu einer mythischen Auseinandersetzung und dem Einsatz einer Superwaffe, die in der Stadt große Zerstörung anrichten und sogar das Ende des Nebels herbeiführen könnte.","sz":9.5,"box":[53.9,330.1,283.1,489.6],"p":234,"i":1,"sec":"titel-und-pitch"},{"t":"p","x":"Anders als die meisten Fälle spielt sich <i>Die Straßen bluten Neon</i> eher wie ein Sandbox-Event als wie eine lineare Untersuchung. Es besteht aus einer Reihe lose miteinander verbundener Szenenkomponenten, die nicht durch Hinweise, sondern durch die Entscheidungen und Handlungen der SC und der Haupt-NSC aufeinander verweisen. Es liegt an dir als Spielleitung, jede Szene auf Grundlage der Entwicklung der Ereignisse an dein Spiel anzupassen.","sz":9.5,"box":[53.9,498.3,282.0,607.8],"p":234,"i":2,"sec":"titel-und-pitch"},{"t":"p","x":"Daher kann sich <i>Die Straßen bluten Neon</i> jedes Mal, wenn du es leitest, unterschiedlich entwickeln. Der Ausgang jeder Szene hängt stark von den Handlungen der SC ab. Das Team könnte beide Seiten unterstützen und die Loyalität während des Falls wechseln.","sz":9.5,"box":[53.9,616.5,282.2,676.0],"p":234,"i":3,"sec":"titel-und-pitch"},{"t":"p","x":"Zu Beginn des Falles befindet sich die Stadt inmitten eines Bandenkriegs zwischen der Organisation des Gralsritters Vince Beaumont (König Artus) – von den Medien als <b>Whitecliff-Syndikat</b> bezeichnet – und rivalisierenden Rissbanden und Verbrecher:innen sowie der Polizei, die die Torwächter:innen heimlich unterstützen.","sz":9.5,"box":[309.0,59.9,537.3,144.4],"p":234,"i":4,"sec":"titel-und-pitch"},{"t":"p","x":"Das Whitecliff-Syndikat operiert von dem aus, was sie <b>das Königreich Albion</b> nennen, eine legendäre Enklave des mythischen Britannien, die im Arbeiterviertel Whitecliff (oder am Rande der Stadt, s. u.) entstand und sich unter Beaumonts Kontrolle in ein autarkes Land verwandelt hat. Beaumonts Bande, <b>die Fahrenden</b>, hält die Stellung gegen rivalisierende Banden und die Polizei und schickt Trupps aus, um blutige Rache an Rival:innen zu üben, die sie als feindliche Invasor:innen betrachten. Aus Sicht der Schläfer:innen ist Whitecliff ein Viertel, wo das organisierte Verbrechen herrscht und in das die Polizei keinen Fuß mehr setzen kann. Die Riss-Verbrecher:innen, die Albions Unabhängigkeit als Eingriff in ihr Territorium betrachten, bezeichnen Beaumonts Bande als „<b>Sezessionist:innen</b>“ und nehmen die Fahrenden ins Visier, wo immer sie auftauchen.","sz":9.5,"box":[309.0,153.1,540.6,362.6],"p":234,"i":5,"sec":"titel-und-pitch"},{"t":"p","x":"Die Grenze zwischen Albion und der Stadt läuft entlang mehrerer Autobahnen, die die Enklave abgrenzen. Durch die verstärkte Präsenz von Regierungsagent:innen in grauen Anzügen (den Torwächter:innen) haben die Medien sie in Anlehnung an den unter Rissen kursierenden Begriff „<b>Gazevorhang</b>“ genannt. In den so genannten „<b>Grenzlande</b>“ auf beiden Seiten des Gazevorhangs patrouillieren alle beteiligten Parteien.","sz":9.5,"box":[309.0,371.3,540.7,468.3],"p":234,"i":6,"sec":"titel-und-pitch"},{"t":"sh","x":"<b>DER ZUSTAND ALBIONS</b>","sz":10.0,"box":[309.4,481.9,438.9,491.9],"p":234,"i":7,"sec":"titel-und-pitch"},{"t":"p","x":"Wenn du den Fall als Einzelszenario leitest, ist Albion wie oben beschrieben: ein teils modernes, teils mittelalterliches Stadtviertel, von Magie übernommen. Wenn du die Kampagne leitest, hängt die Beschaffenheit Albions in deinem Spiel vom Ausgang der vorangegangenen Fälle dieser Ebene ab: <i>Albion erwache!</i> (s. S. 181) und <i>Daheim ist daheim</i> (s. S. 209).","sz":9.5,"box":[309.0,497.4,541.3,581.9],"p":234,"i":8,"sec":"titel-und-pitch"},{"t":"p","x":"• Wenn das Team in <i>Albion erwache!</i> die Schaffung des Königreichs verhindert hat, haben sich die Flüchtlinge und Verbannten in einer Barackenstadt am Rande der Stadt niedergelassen, in der Beaumont die Enklave neu errichtet. Statt des glorreichen Königreichs, ist <b>Neu-Albion</b> nun ein trostloses, wolkenverhangenes Land voller verbitterter Seelen, die einen Groll auf das Team hegen.","sz":9.5,"box":[309.0,593.4,541.3,690.4],"p":234,"i":9,"sec":"titel-und-pitch"}],"size":[595.276,841.89]},"235":{"tab":"","blocks":[{"t":"p","x":"• Wenn das Team keine Maßnahmen ergriffen hat, um Eva Rices Taten in <i>Daheim ist daheim</i> rückgängig zu machen, hat sich Albion in den verlassenen Vierteln ausgebreitet, die die Immobilienmaklerin hinterlassen hat, wie z. B. Wildknock, und ist jetzt eine flächenmäßig größere und mächtigere militärische Kraft, die dem Rest der Stadt ebenbürtig ist.","sz":9.5,"box":[53.9,59.9,283.5,144.4],"p":235,"i":0,"sec":"titel-und-pitch"},{"t":"p","x":"• Falls sich Teammitglieder Beaumont angeschlossen haben, befinden sie sich auf der Albion-Seite des Gazevorhangs, und arbeiten für ihn.","sz":9.5,"box":[53.9,153.1,279.8,187.6],"p":235,"i":1,"sec":"titel-und-pitch"},{"t":"h","x":"TOXISCHER KRIEG ZWEIER PATEN","sz":16.0,"box":[53.9,200.4,274.9,216.4],"p":235,"i":2,"skip":true,"sec":"toxischer-krieg-zweier-paten"},{"t":"p","x":"<b>Hinter den Kulissen ist der Krieg zwischen dem Whitecliff-Syndikat und der Polizei der Krieg zweier Könige der Neuzeit: Vince Beaumont und dem „König in Karmesin“ alias Corbin Payne.</b>","sz":9.5,"box":[53.9,220.5,273.9,267.5],"p":235,"i":3,"sec":"toxischer-krieg-zweier-paten"},{"t":"p","x":"Vor langer Zeit, als die Stadt noch jung war, versuchte Vince Beaumonts Tochter Rio zu verhindern, dass sich Payne zum Schmerzensbringer über die Stadt erhob. Sie scheiterte und verschwand spurlos, und der Kummer über ihren Verlust erfüllte ihren Vater mit Wut. Payne nutzte dies, um Beaumont die Nimmer heilende Wunde (s. S. 18) zuzufügen. Er wusste genau, dass ein Krieg zwischen den beiden Königen das größte Leid für die gesamte Stadt bedeuten würde. Im Laufe der Jahre hat Beaumont an Einfluss gewonnen und seine Fähigkeit verfeinert, sein kriminelles Imperium aus der Asche wieder aufzubauen. Wann immer er starb, reinkarnierte er, und wann immer es ihm gelang, Payne zu töten, erweckte der Gral den Fischerkönig wieder zum Leben. Beaumont empfindet den Drang nach mehr Macht, in der Hoffnung, der göttlichen Macht des Grals zu trotzen, was ihn unweigerlich dazu bringt, mehr Schaden anzurichten.","sz":9.5,"box":[53.9,276.0,285.1,498.0],"p":235,"i":4,"sec":"toxischer-krieg-zweier-paten"},{"t":"p","x":"<b>Die Stunde ist gekommen, da die beiden Könige in der Arena der Stadt gegeneinander antreten, doch das Spiel ist bereits gewonnen.</b>","sz":9.5,"box":[53.9,506.8,282.3,541.3],"p":235,"i":5,"sec":"toxischer-krieg-zweier-paten"},{"t":"p","x":"Auf der einen Seite steht Corbin Payne, der verwundete Quell aller Wunden, unglücklich, abgestumpft vom Schmerz und gleichgültig sich selbst und allen anderen gegenüber. Er will Beaumont benutzen, um die Stadt zu vernichten, und während er mit der einen Hand die Fäden zieht, um die Polizei und die Torwächter:innen in den Krieg zu treiben, verzögert er mit der anderen Hand Beaumonts Niederlage und hilft ihm, den Krieg zu eskalieren.","sz":9.5,"box":[53.9,549.9,286.3,659.4],"p":235,"i":6,"sec":"toxischer-krieg-zweier-paten"},{"t":"p","x":"Auf der anderen Seite ist Beaumont ein Spielball seines Kontrahenten, ohne zu wissen, dass er ein Gralsritter ist, der im Dienste seines größten Feindes steht. Er verbirgt seine Motive hinter dem Anschein von Ritterlichkeit und hohen Idealen, doch in Wahrheit ist er von seiner Wut geblendet und sucht nur eines – die Macht, seinen Feind zu vernichten, koste es, was es wolle.","sz":9.5,"box":[53.9,668.0,286.1,752.5],"p":235,"i":7,"sec":"toxischer-krieg-zweier-paten"},{"t":"h","x":"DIE KÖNIGIN VON CAMELOT","sz":14.0,"box":[319.6,61.8,448.9,75.8],"p":235,"i":8,"sec":"toxischer-krieg-zweier-paten"},{"t":"p","x":"Dank der arthurischen Kräfte und der Tatsache, dass die Stadt einen Retter braucht, reinkarniert Beaumont nach dem Tod in einem neuen Wirt (s. S. 182).","sz":9.0,"box":[319.6,88.4,523.4,133.4],"p":235,"i":9,"sec":"toxischer-krieg-zweier-paten"},{"t":"p","x":"Wenn Vince Beaumonts früherer Wirt, Calvin Cyrus, zu Tode gekommen ist, wäre die nächste Inkarnation <b>Monique R. Juarez</b>, eine LKW-Fahrerin Mitte zwanzig, die den Straßennamen <b>MoniqueR</b> annimmt und die Fahrenden mit eiserner Faust führt.","sz":9.0,"box":[319.6,142.1,529.2,199.1],"p":235,"i":10,"sec":"toxischer-krieg-zweier-paten"},{"t":"h","x":"DAS ZENTRALE DILEMMA FÜR DIE SPIELER:INNEN","sz":16.0,"box":[309.0,223.8,474.0,256.8],"p":235,"i":11,"skip":true,"sec":"das-zentrale-dilemma-fuer-die-spieler-innen"},{"t":"p","x":"Der Fall spielt sich am besten, wenn die SC nicht sicher sind, welcher Seite sie helfen sollen, und nach und nach entdecken, dass keine Seite unschuldig ist und der Krieg selbst die größte Bedrohung für die Stadt darstellt. Alle Fraktionen in diesem Krieg sind tief verwundet, weshalb sie sich gegenseitig leiden lassen – das ist der größte Sieg des Königs in Karmesin. Während Beaumonts Verbrechen in diesem Fall im Mittelpunkt stehen, ist der heimtückische Einfluss des Königs in Karmesin nicht so sichtbar. <b>Um das Dilemma zu verstärken, solltest du den Spieler:innen helfen, Beaumonts Gewalttätigkeit zu rechtfertigen, zumindest am Anfang,</b> und zwar so:","sz":9.5,"box":[309.0,260.7,541.2,420.4],"p":235,"i":12,"sec":"das-zentrale-dilemma-fuer-die-spieler-innen"},{"t":"sh","x":"<b>ALBION IDOLISIEREN</b>","sz":10.0,"box":[309.4,433.8,427.4,443.8],"p":235,"i":13,"sec":"das-zentrale-dilemma-fuer-die-spieler-innen"},{"t":"p","x":"<b>Erstens: Stelle Albion als eine entstehende Utopie dar, eine wundersame Alternative zur profanen Stadt.</b> Die Bewohner scheinen glücklicher zu sein, sie leben auf dem Lande, wo der Nebel dünn und es leichter ist, man selbst zu sein. Es ist ein Ort, an dem man frei sein, das Königreich durchstreifen und seine Legende ausleben kann. Eine gerechte Tafelrunde der Besten regiert die Enklave, und alle sind respektvoll und ritterlich. Das kann die Romantiker:innen im Team ansprechen, aber auch Zyniker:innen könnten sich zu Gläubigen entwickeln und sich für die Verteidigung eines solchen Traums einsetzen. (Es gibt eine dunkle Seite Albions und der Fahrenden, die es regieren, die sich im Laufe des Falles enthüllt).","sz":9.5,"box":[309.0,449.5,535.9,621.4],"p":235,"i":14,"sec":"das-zentrale-dilemma-fuer-die-spieler-innen"},{"t":"sh","x":"<b>DER KÖNIG IN KARMESIN ALS SCHURKE</b>","sz":10.0,"box":[309.4,635.0,527.9,645.0],"p":235,"i":15,"sec":"das-zentrale-dilemma-fuer-die-spieler-innen"},{"t":"p","x":"<b>Zweitens: Baue den Königs in Karmesin als schlimmster Feind der Stadt auf.</b>","sz":9.5,"box":[309.0,650.7,504.1,672.7],"p":235,"i":16,"sec":"das-zentrale-dilemma-fuer-die-spieler-innen"},{"t":"p","x":"Wenn du die gesamte Kampagne leitest und das Team mindestens eine Ebene abgeschlossen hat, <b>spiele darauf an, was es bereits über Corbin Payne weiß</b>: die persönlichen Geschichten der Opfer Dr. Krystal Knights und/oder Armand Kais oder das eigene Leiden des Teams, wenn es schon mit Payne aneinandergeraten ist. Payne scheint sich daran zu erfreuen, überall","sz":9.5,"box":[309.0,681.3,538.0,765.8],"p":235,"i":17,"sec":"das-zentrale-dilemma-fuer-die-spieler-innen"}],"size":[595.276,841.89]},"236":{"tab":"","blocks":[{"t":"p","x":"für jeden Leid zu verursachen, indem er aus der Ferne die Fäden zieht. Seine Reichweite scheint endlos und seine Herrschaft ewig, ähnlich wie ein dunkler Herrscher, der über der Stadt und Albion schwebt. Beaumonts Bemühungen mögen zerstörerisch sein, aber zumindest sind sie geradlinig und gegen das größere Übel gerichtet – ein Übel, dem niemand sonst gewachsen scheint!","sz":9.5,"box":[53.9,59.9,283.2,156.9],"p":236,"i":0,"sec":"das-zentrale-dilemma-fuer-die-spieler-innen"},{"t":"p","x":"Wenn dies die erste Ebene ist oder wenn du den Fall als Einzelabenteuer leitest, <b>spiele mit dem Ruf des Königs in Karmesin</b>. Jeder kennt den Namen des Mannes, der verborgener Herr des Verbrechens gilt, der hinter den Kulissen alles steuert. Er ist indirekt für all die Menschen verantwortlich, die durch geschmuggelte Waffen sterben oder die drogenabhängig sind. Mache ihn zur Ursache für die persönliche Tragödie eines oder mehrerer SC, indem du zeigst, dass die verantwortliche Person auf Anweisung des Königs in Karmesin gehandelt hat. Man gemunkelt, er sei ein Psychopath, dessen Vergnügen darin besteht zuzusehen, wie sich die Stadt selbst verzehrt.","sz":9.5,"box":[53.9,165.6,283.0,325.1],"p":236,"i":1,"sec":"das-zentrale-dilemma-fuer-die-spieler-innen"},{"t":"h","x":"HÄUSERKAMPF UND BANDENKRIEG","sz":16.0,"box":[53.9,340.8,285.7,356.8],"p":236,"i":2,"skip":true,"sec":"haeuserkampf-und-bandenkrieg"},{"t":"p","x":"Der Fall beginnt, als der Bandenkrieg mit einem <u>Blutbad in der Innenstadt</u> einen gewalttätigen Höhepunkt erreicht.","sz":9.5,"box":[53.9,360.7,280.6,395.2],"p":236,"i":3,"sec":"haeuserkampf-und-bandenkrieg"},{"t":"p","x":"In der Zwischenzeit sucht Beaumont nach <b>der ultimativen Waffe</b>, mit der er den König in Karmesin und die Gesetzeshüter:innen der Stadt besiegen kann, die er als direkte Diener:innen seines dunklen Feindes betrachtet. Standardmäßig ist diese Waffe <b>Ray Gibbons</b> (Merlin), ein erwachender junger Riss und der Sohn von <b>Céline Rowland</b> (Herrin vom See), den sie in Miller’s Square <u>(Ray Gibbons’ Junggesellenbude)</u> versteckt hat. Alternativ oder zusätzlich zu Ray Gibbons kann die Superwaffe ein SC oder eine Nebenfigur der Serie sein.","sz":9.5,"box":[53.9,403.9,285.6,538.4],"p":236,"i":4,"sec":"haeuserkampf-und-bandenkrieg"},{"t":"p","x":"Um die Waffe zu finden oder ihre Kräfte freizusetzen, muss Beaumont <b>die Questentier-Queste</b> erfüllen: eine Monstrosität am <u>Steinaltar</u> töten, um eine Vision seiner ultimativen Waffe oder der Mittel, um sie zu","sz":9.5,"box":[53.9,547.0,280.8,594.0],"p":236,"i":5,"sec":"haeuserkampf-und-bandenkrieg"},{"t":"h","x":"GEHEILTE SC UND BRUTALITÄT","sz":14.0,"box":[65.2,615.1,206.7,629.1],"p":236,"i":6,"sec":"haeuserkampf-und-bandenkrieg"},{"t":"p","x":"Wenn du den übergreifenden Fall <i>Parzival</i> verwendest und einer oder mehrere der SC ihren geheimen Schmerz entdeckt und begonnen haben, sich davon zu heilen, frag die Spieler:innen, ob ihre Charaktere das Gefühl haben, dass ihre Einsichten im Widerspruch zu exzessiven Gewalttaten stehen.","sz":9.0,"box":[65.2,641.7,270.3,710.7],"p":236,"i":7,"sec":"haeuserkampf-und-bandenkrieg"},{"t":"p","x":"Wenn dies der Fall ist, können sie wählen, ob der Zustand <t>geheilt</t> Handlungen verhindern soll, von denen der Charakter glaubt, dass sie seinem Verständnis von dem, was notwendig oder hilfreich ist, um die Stadt von ihren Wunden zu heilen, zuwiderlaufen.","sz":9.0,"box":[65.2,719.3,272.6,776.3],"p":236,"i":8,"sec":"haeuserkampf-und-bandenkrieg"},{"t":"p","x":"aktivieren, zu erhalten. Die Rolle der „Monstrosität“ kann jeder SC oder NSC übernehmen, der sich auf abscheuliche Weise vergangen hat, einschließlich eines früheren Bösewichts, einer Nebenfigur oder Nemesis. Wenn du die kriminelle Ebene durchspielst, ist dies <b>Eva Rice</b> (Wendigo), falls sie überlebt hat (s. S. <i>Daheim ist daheim</i>, S. 209).","sz":9.5,"box":[309.0,59.9,538.8,144.4],"p":236,"i":9,"sec":"haeuserkampf-und-bandenkrieg"},{"t":"h","x":"AUSEINANDERSETZUNG MIT DEM KÖNIG","sz":16.0,"box":[309.0,160.1,528.6,193.1],"p":236,"i":10,"skip":true,"sec":"auseinandersetzung-mit-dem-koenig"},{"t":"p","x":"<b>Im Laufe des Falles erhält das Team Beweise dafür, dass der König von Albion außer Kontrolle ist</b>, unabhängig davon, ob sie anfangs zu Beaumonts Verbündeten gehören oder nicht. Bei dem <u>Blutbad in der Innenstadt</u> und seiner Bereitschaft, einen Gefangenen kaltblütig gegen Macht zu tauschen <u>(Der Steinaltar),</u> zeigt Beaumont sein wahres Gesicht.","sz":9.5,"box":[309.0,197.1,539.5,281.5],"p":236,"i":11,"sec":"auseinandersetzung-mit-dem-koenig"},{"t":"p","x":"<b>Da Beaumont reinkarnieren kann, ist es schwierig, ihn aufzuhalten.</b> Wenn die SC dies wollen, müssen sie sowohl seine Vergangenheit als auch seinen einzigartigen Zustand (die Nimmer heilende Wunde mit dem Artus-Mythos kombiniert) erkennen. Da die Uhr tickt und die Feindseligkeiten sich zu einem offenen Krieg ausweiten, könnte die Jagd nach dem <u>Geheimnis des Königs</u> auf Kosten der Bewältigung der aktuellen Krise gehen.","sz":9.5,"box":[309.0,290.3,541.0,399.7],"p":236,"i":12,"sec":"auseinandersetzung-mit-dem-koenig"},{"t":"p","x":"Beaumont ist kein Narr und rechnet mit Verrat. Er hat einen Spion, der SC oder NSC, die sie befragen, überwacht, einen seltsamen Kerl namens <b>MISTER BAR- LOW</b> (Burlow Beanie, ein siebenköpfiger Kobold aus der Artussage), der ihm persönlich Bericht erstattet. Wenn es den SC gelingt, etwas über die Vergangenheit herauszufinden, wird Beaumont sich ihrer entledigen.","sz":9.5,"box":[309.0,408.4,537.0,492.9],"p":236,"i":13,"sec":"auseinandersetzung-mit-dem-koenig"},{"t":"h","x":"DER PREIS DES KRIEGES","sz":16.0,"box":[309.0,508.5,466.4,524.5],"p":236,"i":14,"skip":true,"sec":"der-preis-des-krieges"},{"t":"p","x":"Während die Suche nach einer Superwaffe oder den Geheimnissen des Königs im Gange ist, eskaliert der Krieg zwischen Albion und der Stadt weiter. Schließlich starten die Strafverfolgungsbehörden, die Armee und die Torwächter:innen einen letzten Angriff auf die Festung Albions. Die <u>Schlacht an der Calmann-Brücke</u> endet mit vielen Toten und Verwundeten auf beiden Seiten, wenn das Team nicht eingreift.","sz":9.5,"box":[309.0,528.4,539.9,625.4],"p":236,"i":15,"sec":"der-preis-des-krieges"},{"t":"p","x":"Gleichzeitig drohen die Macht Albions oder die Entfesselung von Beaumonts Superwaffe den Nebel zu zerreißen und führen zu <u>Rissen allüberall.</u> Monster wüten in den Straßen, Mythen des Unheils und der Bösartigkeit, angezogen von der blutgetränkten Aura des Krieges.","sz":9.5,"box":[309.0,634.1,532.5,706.1],"p":236,"i":16,"sec":"der-preis-des-krieges"},{"t":"p","x":"Am Ende muss sich jedes Teammitglied entscheiden: sich im Krieg auf eine Seite stellen und zusehen, wie die Stadt in Schutt und Asche versinkt, oder sie retten, indem sie Beaumont von seinem Wahn heilen, seinen Feind um jeden Preis zu vernichten.","sz":9.5,"box":[309.0,714.8,538.6,774.3],"p":236,"i":17,"sec":"der-preis-des-krieges"}],"size":[595.276,841.89]},"237":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 0:","sz":14.0,"box":[53.9,442.5,122.3,456.5],"p":237,"i":0,"skip":true,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"AUFHÄNGER","sz":23.0,"box":[53.9,464.8,170.2,487.8],"p":237,"i":1,"skip":true},{"t":"p","x":"Folgendermaßen kannst du das Team in den Fall einbeziehen:","sz":9.5,"box":[53.9,496.2,278.0,518.2],"p":237,"i":2,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• Wenn die SC nach <i>Albion erwache!</i> oder <i>Daheim ist daheim</i> für <b>Vince Beaumont</b> arbeiten, geraten sie indirekt in die Ereignisse dieses Falles hinein. Beaumont könnte sie beauftragen, einen Überfall auf eine rivalisierende Bande in der Innenstadt anzuführen <u>(Blutbad in der Innenstadt)</u> oder, falls sie Eva Rice gefangen genommen haben, verlangen, dass sie sie nach Albion <u>(Die Grenzlande)</u> schmuggeln, um bei dem Opferritual <u>(Der Steinaltar)</u> als Questentier zu fungieren. SC, die in <u>Camelot</u> willkommen sind, könnten anfangen, an Beaumonts Verstand zu zweifeln und herumschnüffeln.","sz":9.5,"box":[53.9,529.7,285.3,676.7],"p":237,"i":3,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• Wenn das Team in Albion nicht willkommen ist oder auf keiner der Seiten steht, <b>nimmt vielleicht der unorthodoxe Agent und Riss-Lenker der Torwächter:innen, Lars Erikson</b>, Kontakt mit den SC auf. Erikson wird behaupten, eine geheimnisvolle dritte Macht zu vertreten, der sehr daran gelegen ist, die Situation zu entschärfen. Er wird das Team an-","sz":9.5,"box":[53.9,685.4,284.5,769.9],"p":237,"i":4,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"heuern oder anstiften, Albion <u>(Die Grenzlande)</u> und <u>Camelot</u> zu infiltrieren, um wichtige Informationen über Beaumont und die Armeen zu sammeln – und darüber, wie man sie besiegen kann. Er könnte die SC beauftragen, das Ritual am <u>Steinaltar</u> zu beobachten oder zu stören.","sz":9.5,"box":[317.5,440.5,541.3,512.5],"p":237,"i":5,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• Wenn der Bandenkrieg eskaliert, können die Mitglieder des Teams oder Nebenfiguren zwischen die Fronten geraten. Passanten in der Nähe des <u>Blutbads in der Innenstadt</u> geraten ins Kreuzfeuer, was die SC dazu bringt, Rache zu schwören. Rivalisierende Gangs – die Adze (s. S. 242) – können das Team anheuern, um den Ansturm zurückzudrängen. Albion könnte es engagieren, um mitzukämpfen, die Grenzen <u>(Die Grenzlande)</u> zu bewachen oder um eine der Seiten zu überfallen. Am wahrscheinlichsten ist es, dass man die SC als Kopfgeldjäger:innen anheuern will, um einen Gauner zu finden, der hässlich genug ist, um als Questentier <u>(Der Steinaltar)</u> zu dienen. NSC, die dem Team nahe stehen, können das Ziel des Auftrags sein und die SC zwingen, sie zu beschützen. Das Gleiche könnte Feinden der SC passieren, was das Team vielleicht veranlasst, beim Ritual aufzutauchen, um sich hämisch zu freuen und sicherzustellen, dass ihre Feinde dem Schwert zum Opfer fallen.","sz":9.5,"box":[309.0,521.1,541.3,755.6],"p":237,"i":6,"sec":"schicht-0-aufhaenger"}],"size":[595.276,841.89]},"238":{"tab":"","blocks":[{"t":"h","x":"MISTER BARLOW","sz":23.0,"box":[54.6,63.4,217.3,86.4],"p":238,"i":0,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"Unabhängig davon, ob es sich bei den SC um Spione in Albion oder um loyale Mitglieder des Whitecliff- Syndikats handelt, will Vince Beaumont ein Auge auf sie haben, um jeden Verrat zu verhindern. Zu diesem Zweck hat er ein Wesen beschworen, das ihm als Agent dienen soll: <b>Mister Barlow</b>, eine Inkarnation des siebenköpfigen Geistes Burlow Beanie aus der Artussage.","sz":9.5,"box":[54.6,94.9,285.6,179.4],"p":238,"i":1,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"In der Stadt erscheint Barlow als athletischer junger Mann mit bösem Gesicht, gekleidet in einen knielangen, wattierten Trenchcoat und Weste, der oft einen Spazierstock trägt. Dieser viktorianische Touch, der für Risse deutlich sichtbar ist, vermittelt den Eindruck, er sei ein anrüchiger Geschäftemacher für die Gewerkschaft, die Unterwelt oder beides. Oft trägt er Kappe oder Hut so, dass sein vernarbtes Gesicht halb verdeckt ist, was die unheimliche Präsenz noch verstärkt.","sz":9.5,"box":[54.6,188.0,286.5,297.5],"p":238,"i":2,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"Entgegen dem Anschein ist Mister Barlow weder ein einzelnes Wesen noch ein Mensch sondern ein Schatten aus der Enklave Albion. Mister Barlow existiert als bis zu sieben separate Kopien seiner selbst, die unabhängig voneinander umherstreifen und Spionage und Mordanschläge für Beaumont verüben. Alle Exemplare von Mister Barlow verfügen über eine Schwarmintelligenz, aber keinen eigenen Willen.","sz":9.5,"box":[54.6,306.2,284.8,403.2],"p":238,"i":3,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"Beaumont wird den Kobold auf folgende Weise einsetzen:","sz":9.5,"box":[54.6,411.9,270.5,433.9],"p":238,"i":4,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Spionage</b>: Die verschiedenen Kopien Barlows beobachten die SC. Verwende eine harten Aktion oder einen Wurf von 7-9 auf <b>Nachforschungen</b>, um ihn etwas Nützliches finden zu lassen und es Beaumont mitzuteilen (Beaumont trifft normalerweise eine der Kopien in Camelot. Wenn die Kopie woanders im Einsatz ist, ruft Barlow einfach an, um zu berichten).","sz":9.5,"box":[54.6,445.4,284.8,529.9],"p":238,"i":5,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Mobbing</b>: Wenn Beaumont den Verdacht hat, ein SC, den er mag oder braucht, könne ihn verraten, beauftragt er Mister Barlow, diesen einzuschüchtern. Falls das gelingt, hat der SC mit einem zwanghaften Zustand (<t>eingeschüchtert 3</t>) zu kämpfen, der ihn hindert, entgegen Mister Barlows „Rat“ von zu handeln.","sz":9.5,"box":[54.6,538.5,286.0,610.5],"p":238,"i":6,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Meuchelmord</b>: Wenn jemand Beaumont verrät oder der SC Barlows Warnung ignoriert hat, befiehlt Beaumont dem Kobold, sich „um ihn zu kümmern“. Mister Barlow wird zuschlagen, wenn das Ziel am verwundbarsten ist, wobei mehrere Exemplare gleichzeitig angreifen können (vor allem, wenn das Ziel allein ist und Mister Barlow glaubt, sein Mehrkörpergeheimnis sei sicher, wenn das Ziel tot ist). Er bereitet sich gut vor, um die Kräfte des Ziels zu kontern.","sz":9.5,"box":[54.6,619.2,287.0,728.7],"p":238,"i":7,"sec":"schicht-0-aufhaenger"},{"t":"threat","stars":"★★★","name":"MISTER BARLOW +","spectra":"","items":[],"box":[405.3,58.9,435.9,70.9],"p":238,"i":8,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"Als beschworenes Wesen kann man eine Kopie von Mister Barlow leichter <i>bannen</i> als durch <i>Verletzen oder unschädlich machen</i> zu zerstören. Albion muss die Kopie wiederherstellen, was eine oder mehrere Drehpausen dauern kann. Beaumont kann sich entscheiden, dies nicht zu tun, wenn die Enklave geschwächt ist oder eine unmittelbare Bedrohung besteht. Aufgrund seines Mythos können Magiekundige oder übernatürliche Wesen den Burlow Beanie <i>magisch kontrollieren</i> (in der Artussage übernimmt der Grüne Ritter ihn und benutzt ihn, um den König von Cornwall zu besiegen). Wenn die SC eine Kopie von Mister Barlow übernehmen, gib ihnen das zusätzliche Thema auf der nächsten Seite. Sie können wählen, was diese den anderen Kopien mitteilt.","sz":9.0,"box":[318.1,82.0,533.3,259.0],"p":238,"i":9,"sec":"schicht-0-aufhaenger"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 5 / BAN- NEN 3 / MAGISCH KONTROLLIEREN 6</b>","sz":12.0,"box":[318.1,269.5,526.7,293.5],"p":238,"i":10,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Körperloser Geist</b>: Man kann ihn mit weltlichen Mitteln nicht verletzen. Angriffe gehen durch ihn hindurch. • <b>Hinterhältig</b>: Wenn Barlow zu Beginn einer Szene ungesehen bleiben möchte, gib ihm <t>heimlich 2</t>, erneuerbar als harte Aktion. • <b>Vorsatz</b>: Wenn er ein Attentat auf ein Ziel plant, sammelt er Informationen über dessen Fähigkeiten. Immer, wenn das Ziel oder Verbündete 7-9 auf <b>Nachforschungen</b> würfelt, erfährt er ein Detail. Als harte Aktion kann er drei Details erfahren. Für jedes Detail, das er erfahren hat, bereitet Mister Barlow ein Stück weltliche Ausrüstung oder eine Falle vor, die ein Geschichten-Marker abbildet. Wenn er zuschlägt, kann er die Marker nutzen, um die Aktionen des Ziels zu behindern, oder sie verbrennen, um 1:1 Stärken des Ziels zu verbrennen.","sz":9.0,"box":[318.1,298.0,528.8,499.0],"p":238,"i":11,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• Jemanden fachgerecht mit dem Taschenmesser abstechen (<t>tiefe Stichwunde 3</t>) • Drohen zuzuschlagen, wenn man es am wenigsten erwartet, und Koboldaugen zeigen (<t>eingeschüchtert 3</t>) • <i>Unsichtbar</i> werden, sich verstecken oder flüchten • Wenn unsichtbar: ganz entkommen (<b>Ihnen etwas verweigern, das sie wollen</b>)","sz":9.0,"box":[318.1,508.0,530.3,601.1],"p":238,"i":12,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• Mit einem verschmitzten Lächeln halb aus dem Schatten treten • Sich jemandem beängstigend dicht nähern und ihm einen Schauer über den Rücken jagen • Ein verstecktes Taschenmesser zücken, das im Mondlicht glänzt","sz":9.0,"box":[318.1,610.0,532.7,679.0],"p":238,"i":13,"sec":"schicht-0-aufhaenger"}],"size":[595.276,841.89]},"239":{"tab":"","blocks":[{"t":"sh","x":"<b>MISTER BARLOW</b>","sz":12.0,"box":[64.9,62.6,166.3,74.6],"p":239,"i":0,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"<i>Beschwörung</i>","sz":10.0,"box":[64.9,84.3,129.3,94.3],"p":239,"i":1,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"IDENTITÄT","sz":10.0,"box":[64.9,105.8,111.2,115.8],"p":239,"i":2,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"Wer konspiriert gegen meinen Meister?.","sz":9.0,"box":[64.9,120.6,223.2,129.6],"p":239,"i":3,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"STÄRKEN","sz":10.0,"box":[64.9,141.3,105.6,151.3],"p":239,"i":4,"sec":"schicht-0-aufhaenger"},{"t":"card","x":"<b><i>Mörderischer Kobold</i></b>, <i>Einfallsreicher Diener</i>, <i>Mehrere Barlows</i>, <i>Teuflischer Messerkampf</i>, <i>Feinde ausspionieren</i>, <i>Warnung vor Verrat</i>, <i>Stärker in Albion</i>, <i>Durch legendäre Waffen verwundbar</i>, <i>Gegenstand gegen eine Fähigkeit</i>, <i>Durch Magie gebunden</i>","sz":null,"k":"yellow","box":[65.1,154.9,274.2,213.1],"p":239,"i":5,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"SCHWÄCHEN","sz":10.0,"box":[64.9,224.8,121.9,234.8],"p":239,"i":6,"sec":"schicht-0-aufhaenger"},{"t":"card","x":"<i>Weit weg von Albion</i>, <i>Blutrünstig</i>, <i>An Beaumont gebunden</i>, <i>Verlässt sich auf Beobachtungen</i>","sz":null,"k":"yellow","box":[65.1,238.5,250.6,260.4],"p":239,"i":7,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"THEMENVERBESSERUNG","sz":10.0,"box":[64.9,272.3,171.7,282.3],"p":239,"i":8,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"<b>Vorsatz:</b> Wenn Mister Barlow ein Attentat plant, kannst du Hinweise, die Wissen über Stärken und Schwächen des Ziels repräsentieren, in den vorübergehenden Zustand <i>Gut vorbereitet</i> mit einer Stufe, die der Anzahl der Hinweise entspricht, umwandeln. Wenn du mehrere Chargen an Hinweisen hast, wandle sie separat um und nutze sie kumulativ.","sz":9.0,"box":[64.9,287.1,274.5,368.1],"p":239,"i":9,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"SCHICHT 1:","sz":14.0,"box":[309.0,61.9,376.0,75.9],"p":239,"i":10,"skip":true,"sec":"schicht-1-scharmuetzel-an-den-grenzen"},{"t":"h","x":"SCHARMÜTZEL AN DEN GRENZEN","sz":23.0,"box":[309.0,84.2,472.5,135.2],"p":239,"i":11,"skip":true},{"t":"p","x":"In der ersten Schicht des Falles befindet sich die Stadt in einer eskalierenden Krise zwischen der Polizei, mehreren Riss-Banden und dem Whitecliff-Syndikat. Obwohl die Situation angespannt ist, ist sie noch nicht in einen totalen Krieg ausgeartet. Noch machen sich die SC mit der Situation vertraut, während sie an einigen der illegalen – manchmal geradezu unmoralischen – Aktivitäten teilnehmen, die im Wettstreit um die Kontrolle über die Stadt stattfinden.","sz":13.0,"box":[309.0,143.1,539.0,315.6],"p":239,"i":12,"sec":"schicht-1-scharmuetzel-an-den-grenzen"},{"t":"p","x":"Wenn die SC auf dem Weg von der Stadt nach Albion sind (wenn sie Beaumont in <u>Camelot</u> auszuspionieren oder Gefangene zum <u>Steinaltar</u> bringen) oder einen Angriff von Albion in der Stadt durchführen <u>(Blutbad in der Innenstadt),</u> <b>müssen sie zuerst <u>die Grenzlande</u> durchqueren</b> – es sei denn, sie haben eine bessere Möglichkeit, Grenze und Gazevorhang zu überwinden.","sz":9.5,"box":[309.0,326.2,537.9,410.7],"p":239,"i":13,"sec":"schicht-1-scharmuetzel-an-den-grenzen"},{"t":"h","x":"DIE GRENZLANDE","sz":16.0,"box":[334.8,427.3,446.8,443.3],"p":239,"i":14,"skip":true,"sec":"die-grenzlande"},{"t":"ro","x":"Unter der Autobahn gibt es nur nackte Betonflächen und unbebaute Grundstücke, die unkrautüberwuchert und von Maschendrahtzäunen und rostigen, verketteten Toren gesäumt sind. Ein breiter Zementkanal, bis auf ein paar ölige Pfützen trocken, markiert die Grenze zu Albion. Schüsse, Motorräder und Polizeisirenen hallen in der Ferne wider. Auf beiden Seiten brennen Tonnen, deren Flammen lange Schatten auf die Zementsäulen und Rampen werfen, wo sich vermummte dunkle Gestalten wärmen, Wache halten und zweifellos versteckte Waffen tragen. Jede falsche Bewegung könnte dieses Pulverfass entzünden und den dunklen Kanal in explosive Gewalt ausbrechen lassen.","sz":9.0,"box":[317.5,445.7,538.9,627.5],"p":239,"i":15,"sec":"die-grenzlande"},{"t":"p","x":"Die Grenzlande sind die Gebiete beiderseits der Autobahnen, die die Enklave Albion abgrenzen, je etwa einen Häuserblock tief. Während die Fahrenden die Straßen und Autobahnausfahrten ins Viertel verbarrikadiert haben und die Polizei und Nachrichtenreporter:innen diese Barrikaden belagern, sind die Grenzgebiete zu ausgedehnt, um sie dauerhaft zu verteidigen. Stattdessen patrouillieren alle beteiligten Fraktionen in den Grenzlanden und setzen Späher:innen, Spion:innen und Informant:innen ein, um das Kommen und Gehen Anderer zu beobachten und jeden Angriff","sz":9.5,"box":[309.0,636.5,539.3,771.0],"p":239,"i":16,"sec":"die-grenzlande"}],"size":[595.276,841.89]},"240":{"tab":"","blocks":[{"t":"p","x":"an diesen Fronten zu verhindern. Infolgedessen sind die Grenzlande ein stilles, unheimliches Niemandsland, das die Bewohner:innen der Stadt fürchten und Schmuggler:innen oder Saboteur:innen, die sich in feindliches Gebiet wagen wollen, bevorzugen.","sz":9.5,"box":[53.9,378.1,276.7,437.6],"p":240,"i":0,"sec":"die-grenzlande"},{"t":"p","x":"<b>Die Grenzlande stellen eine Infiltrations-Herausforderung dar, die als spannender Einstieg in die Lage der Stadt dient.</b> Das Team muss sie durchqueren, um zum nächsten Schauplatz zu gelangen. Wenn es sich auf den Weg nach oder aus Albion macht, ist dies der Weg des geringsten Widerstands. Da jedoch alle Fraktionen in Aufruhr sind, könnte jedes Anzeichen von Aktivität in den Grenzlanden die Feind:innen des Teams (Fahrende, Polizei, rivalisierende Banden oder Torwächter:innen) auf den Plan rufen, eine blutige Schlacht entfachen und das, was das Team zu erreichen versucht, vereiteln. <b>Um an sein Ziel zu gelangen, muss das Team daher einen Weg finden, heimlich die Grenze zu überschreiten.</b>","sz":9.5,"box":[53.9,446.4,286.2,618.4],"p":240,"i":1,"sec":"die-grenzlande"},{"t":"p","x":"Zu den Grenzlanden gehören auch der Luftraum über der Grenze, wo Polizeihubschrauber und auf Greifen reitende Fahrende fliegende SC abfangen können, die Kanalisation, wo unvorsichtigen Infiltrator:innen im Dunkeln aufgelauert wird, und sogar magische Transportmittel: Der von den Torwächter:innen errichtete Gazevorhang könnte Risse in einem grellen Feuerwerk gegen eine leuchtende Wand prallen lassen und ein bis an die Zähne bewaffnetes Empfangskomitee auf den Plan rufen.","sz":9.5,"box":[53.9,627.0,284.7,749.0],"p":240,"i":2,"sec":"die-grenzlande"},{"t":"sh","x":"<b>UNBEMERKTER GRENZÜBERTRITT</b>","sz":10.0,"box":[309.4,381.0,498.3,391.0],"p":240,"i":3,"sec":"die-grenzlande"},{"t":"p","x":"SC, die die Grenzlande durchqueren, müssen drei Sektoren überwinden, um ihr Ziel zu erreichen:","sz":9.5,"box":[309.0,396.5,536.6,418.5],"p":240,"i":4,"sec":"die-grenzlande"},{"t":"p","x":"• Das Grenzgebiet auf der Ausgangsseite der SC (Späher:innen und Patrouillen) • Die Grenze (Überquerung der Autobahn oder des Kanals und des Gazevorhangs) • Das Grenzgebiet auf der anderen Seite (Späher:innen und Patrouillen)","sz":9.5,"box":[309.0,424.4,541.3,496.4],"p":240,"i":5,"sec":"die-grenzlande"},{"t":"p","x":"<b>Jeder Sektor birgt eigene Herausforderungen</b>. Vielleicht möchtest du auf eine Seite verzichten (am Ausgangspunkt oder am Ziel), wenn die SC dort willkommen sind. Sobald die SC die Bedrohungen in allen drei Sektoren überwunden oder umgangen haben, sind sie sicher auf der anderen Seite.","sz":9.5,"box":[309.0,502.2,539.4,574.2],"p":240,"i":6,"sec":"die-grenzlande"},{"t":"p","x":"Wenn das Team auf Widerstand stößt, können es entscheiden, den Besuch auf der anderen Seite zu vertagen. Mach ihnen das Leben schwer, indem du die Folgen der Verzögerung beschreibst. Wenn sie zum Beispiel zum <u>Steinaltar</u> gehen, könnte die Gefangene erwachen, Beaumont oder Erikson könnten <t>böse 2</t> sein, weil sie die Aufgabe nicht rechtzeitig erfüllt haben.","sz":9.5,"box":[309.0,582.9,541.0,667.4],"p":240,"i":7,"sec":"die-grenzlande"},{"t":"p","x":"Das Team könnte durchkommen und trotzdem auffallen. Die Information über ihre Einreise kannst du gegen die SC verwenden, indem ihre Feinde sich jetzt besser auf ihren nächsten Angriff vorbereiten können <u>(Blutbad in der Innenstadt)</u> oder ihre Gesichter nun dank der Sensationsjournalistin Reiko (s. S. 179) <t>in den Nachrichten 3</t> sind.","sz":9.5,"box":[309.0,676.0,534.8,760.5],"p":240,"i":8,"sec":"die-grenzlande"}],"size":[595.276,841.89]},"241":{"tab":"","blocks":[{"t":"p","x":"<b>SPÄHER:INNEN auf beiden Seiten bleiben in Deckung und halten Ausschau nach feindlichen Aktivitäten, die sie melden.</b> Dabei haben sie die Zustände <t>versteckt</t> und <t>wachsam</t>. Ersterer behindert <b>Nachforschungen</b>-Aktionen, um sie zu entdecken, letzterer <b>Heimlichkeits</b>-Aktionen, um an ihnen vorbeizuschleichen. Wenn Späher:innen die SC entdecken, alarmieren sie eine Patrouille, oder, wenn die Gefahr groß scheint, ein Einsatzteam. Späher:innen auf beiden Seiten beaufsichtigen normalerweise alle drei Sektoren. Als harte Aktion kannst du schleichende SC entdecken lassen. Als harte Aktion oder als Aktionserschwernis kannst du einen bereits umgangenen Späher seine Aufmerksamkeit neu ausrichten lassen (z. B. wenn er ein Rascheln hört und seinen Blick dorthin wendet, wo die SC sind), was eine neue <b>Heimlichkeits</b>-Aktion erfordert.","sz":9.5,"box":[53.9,62.6,286.6,272.1],"p":241,"i":0,"sec":"die-grenzlande"},{"t":"p","x":"<b>PATROUILLEN tauchen regelmäßig auf beiden Seiten auf, um nach möglichen Problemen Ausschau zu halten und alle abzufangen, die versuchen, die Grenze zu überschreiten.</b> Sie sind leicht zu bemerken, und das Team kann ihnen aus dem Weg gehen, wenn es ihren Zyklus ausgekundschaftet hat. Andernfalls sind sie wachsam und erfordern eine <b>Heimlichkeits</b>-Aktion, um sie zu umgehen. Wenn sie Eindringlinge entdecken, greifen sie an und fordern bei Bedarf Verstärkung an.","sz":9.5,"box":[53.9,280.8,278.7,402.7],"p":241,"i":1,"sec":"die-grenzlande"},{"t":"p","x":"<b>EINSATZTEAMS sind schwer bewaffnete Einheiten, die in Bereitschaft sind, um größere Bedrohungen zu bekämpfen.</b> Sie treffen nur ein, wenn sie gerufen werden, im Rahmen einer harten Aktion.","sz":9.5,"box":[53.9,411.4,280.6,458.3],"p":241,"i":2,"sec":"die-grenzlande"},{"t":"h","x":"EINHEITEN DER FRAKTIONEN","sz":16.0,"box":[53.9,520.8,242.7,536.8],"p":241,"i":3,"skip":true,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"<b><u>Fraktion Späher:innen</u></b>","sz":10.0,"box":[78.1,548.0,225.0,558.0],"p":241,"i":4,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"<b>Albion</b> Als Betrunkene getarnte Spion:innen, Die Fahrenden (s. S. 193)","sz":8.0,"box":[82.7,559.7,377.5,567.7],"p":241,"i":5,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"Mister Barlow (s. S. 238)","sz":8.0,"box":[157.0,571.7,244.1,579.7],"p":241,"i":6,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"<b>Strafverfolgung</b> Als Stadtstreicher:innen verkleidete Streifenwagen (s. S. 286)","sz":8.0,"box":[66.0,584.5,377.6,592.5],"p":241,"i":7,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"Ermittler:innen","sz":8.0,"box":[174.7,596.5,226.4,604.5],"p":241,"i":8,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"<b>Medien</b> Journalistin Reiko (s. S. 179)","sz":8.0,"box":[80.9,609.3,251.3,617.3],"p":241,"i":9,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"<b>Rivalisierende Banden</b> Adze-Glühwürmchen (s. S. 244)","sz":8.0,"box":[54.3,634.1,256.4,642.1],"p":241,"i":10,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"<b>Riss-gestützte</b> Gaffer (s. S. 290) Sturmbringer:innen (s. S. 291)","sz":8.0,"box":[68.0,646.9,386.0,654.9],"p":241,"i":11,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"<b>Strafverfolgung</b>","sz":8.0,"box":[66.0,658.9,122.5,666.9],"p":241,"i":12,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"<b>DIE GRENZE</b> stellt das Team vor mehrere Herausforderungen. Das Überqueren des überwachten Streifens ist schwieriger als das der Grenzgebiete: Die überspannende Autobahn ist <i>Auf dem Präsentierteller</i> und birgt die Gefahr, von einem Fahrzeug getroffen zu werden, während der Betonkanal darunter durch <i>Maschendrahtzäune</i> abgegrenzt ist und Infiltratoren zwingt, durch <i>Nassen Müll</i> oder <i>Ölige Pfützen</i> zu waten.","sz":9.5,"box":[309.0,62.5,539.6,159.5],"p":241,"i":13,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"Um die Überquerung schwieriger zu machen, haben die Torwächter:innen ein Nebelfeld mit dem Namen <b>Gazevorhang</b> errichtet. Er verhindert, dass Mythos- Manifestationen auf der Stadtseite zu sehen sind und die Grenze überschreiten und entzieht Rissen alle aktiven legendären Kräfte (ohne sie anders zu beeinflussen). Das Durchqueren des Vorhangs verbrennt alle Mythos-Stärken oder -Zustände, man kann sie aber auf der anderen Seite wiederherstellen. Die Barriere blockiert Fortbewegungsmittel, die auf Teleportation oder Gestaltwandel beruhen. Wenn die Barriere mehr als 4 Stärken oder einen Stufe-4-Zustand für einen einzigen Effekt abwehren muss, bricht sie dort (<i>Durchdringen 4</i>). Das alarmiert die Torwächter:innen, die dann von der Anwesenheit eines mächtigen Risses wissen. Nicht weit entfernt parkt ein ramponierter Öltankwagen oder Abwassersauger, ein getarntes Torwächter:innen- Grauwaschfahrzeug, das die Barriere aufrechterhält und reparieren kann.","sz":9.5,"box":[309.0,168.2,540.4,402.7],"p":241,"i":14,"sec":"einheiten-der-fraktionen"},{"t":"card","x":"Die Beobachtung der Grauwäscher oder die Untersuchung des Gazevorhangs können darauf hindeuten, dass <b>die Barriere nicht mehr lange halten wird</b> und <b>die Torwächter:innen zu drastischeren Maßnahmen gezwungen sein werden</b> <u>(Schlacht an der Calmann-Brücke),</u> wenn sie Albion weiter abriegeln wollen.","sz":null,"k":"yellow","box":[309.3,412.1,541.7,508.3],"p":241,"i":15,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"<b><u>Patrouillen Einsatzteams</u></b>","sz":10.0,"box":[311.1,548.0,495.1,558.0],"p":241,"i":16,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"Lanzelot (s. S. 206)","sz":8.0,"box":[436.3,559.7,504.6,567.7],"p":241,"i":17,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"SWAT-Team (s. S. 287)","sz":8.0,"box":[430.2,584.5,510.7,592.5],"p":241,"i":18,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"Journalist:in (s. S. 288) Nachrichtenteam, Journalist:in der","sz":8.0,"box":[292.2,609.3,528.9,617.3],"p":241,"i":19,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"Medienagentur Monte Wolfe (s. S. 288)","sz":8.0,"box":[404.0,621.3,537.0,629.3],"p":241,"i":20,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"Adze-Hexe (s. S. 243) -","sz":8.0,"box":[295.0,634.1,471.6,642.1],"p":241,"i":21,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"Sturmwolken (s. S. 291)","sz":8.0,"box":[428.1,647.7,512.8,655.7],"p":241,"i":22,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"<b>Torwächter:innen</b> Grauwäscher (s. S. 290) Torwächter:innen-Agent:innen (s. S. Torwächter:innen-Spezialeinheiten (s.","sz":8.0,"box":[63.0,681.0,536.9,689.0],"p":241,"i":23,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"289), Sicherheitsleute (s. S. 286)","sz":8.0,"box":[275.7,693.0,390.5,701.0],"p":241,"i":24,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"S. 78), Taktische Weber:innen (s. S.","sz":8.0,"box":[408.5,693.0,532.5,701.0],"p":241,"i":25,"sec":"einheiten-der-fraktionen"},{"t":"p","x":"289)","sz":8.0,"box":[462.3,705.0,478.6,713.0],"p":241,"i":26,"sec":"einheiten-der-fraktionen"}],"size":[595.276,841.89]},"242":{"tab":"","blocks":[{"t":"h","x":"BLUTBAD IN DER INNENSTADT","sz":16.0,"box":[79.7,68.9,276.6,84.9],"p":242,"i":0,"skip":true,"sec":"blutbad-in-der-innenstadt"},{"t":"ro","x":"Die Bässe der groovigen, sanften Musik hallen aus dem seltsam kegelförmigen, grob verputzten Gebäude der Lounge- Bar, die eine flackernde Neonreklame als „NEST“ kennzeichnet. Zwielichtige, leger gekleidete Männer patrouillieren mit Maschinenpistolen auf dem Gelände, während sich die Eingangstür öffnet und eine Schlange Clubgänger mit blutunterlaufenen Augen einlässt, die unbedingt hineinwollen. Durch die vergitterten Fenster sieht man ein unheimliches, pulsierendes grünes Licht, das nur schwach das Labyrinth aus miteinander verbundenen Räumen beleuchtet. Der Ort sieht stark befestigt aus, eine harte Nuss, die es zu knacken gilt. Wenn die Fahrenden diese Bande ausschalten wollen, werden sie Blutzoll entrichten müssen.","sz":9.0,"box":[62.4,87.3,283.8,290.7],"p":242,"i":1,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"Das Blutbad im <b>Nest</b> in der Innenstadt dient als Einführung in den stadtweiten Bandenkrieg und zeigt, wie skrupellos Beaumont und seine Fahrenden in ihrem Kampf um den Erhalt Albions vorgehen. Es geht um einen Überfall der Fahrenden auf ihre Feinde, eine vampirische Unterweltgruppierung namens <b>Adze</b>, die außer Kontrolle gerät und in einem blutigen Massaker endet. Es sei denn, die SC greifen ein.","sz":9.5,"box":[53.9,299.7,285.2,396.7],"p":242,"i":2,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"Das Team kann für Beaumont einen Überfall der Fahrenden auf Festung und Waffenlager einer rivalisierenden Bande anführen, als Unbeteiligte in den Konflikt geraten oder als Feinde Albions versuchen, die Fahrenden abzufangen und sich mit den Adze verbünden.","sz":9.5,"box":[53.9,405.3,285.9,464.8],"p":242,"i":3,"sec":"blutbad-in-der-innenstadt"},{"t":"sh","x":"<b>DIE ADZE</b>","sz":10.0,"box":[54.3,478.4,105.6,488.4],"p":242,"i":4,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"<b>Die Adze sind eine Bande, die ein vampirisches- Glühwürmchen berührt und mit Macht erfüllt hat.</b> Jedes Bandenmitglied, „Hexe“ genannt, hat ein Adze-Glühwürmchen im Nacken und folgt den mentalen Befehlen seines Vertrauten. Die Bande handelt mit Waffen und schmuggelt verschiedene Partydrogen, hauptsächlich Heroin und Amphetamine, unter der Straßenmarke „NEID“. Sie betreibt und schützt ihre Hauptnahrungsquelle, einen Drogenumschlagplatz unter dem Deckmantel einer Chillout-Lounge („Nest“), wo ihre Mitglieder Drogenkonsumenten ausbeuten.","sz":9.5,"box":[53.9,494.1,286.1,628.5],"p":242,"i":5,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"Die Adze, die Albion aus ihrem ursprünglichen Lebensraum vertrieben hat, sind die Todfeinde der Fahrenden und haben die Ritterbande an den Grenzen Albions schon mehrfach angegriffen und in Hinterhalte gelockt, ihr Blut getrunken und verschrumpelte Leichen hinterlassen. Die Fahrenden, die ihre gefallenen Brüder rächen wollen, haben nun einen Gegenangriff gestartet. Sie wissen nicht, dass die Bandenmitglieder nur die Wirte der eigentlichen Adze und sie im Begriff sind, möglicherweise unschuldige Leben auszulöschen.","sz":9.5,"box":[53.9,637.2,286.1,759.2],"p":242,"i":6,"sec":"blutbad-in-der-innenstadt"},{"t":"sh","x":"<b>DAS NEST</b>","sz":10.0,"box":[309.4,62.8,362.4,72.8],"p":242,"i":7,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"<b>Das Nest ist eine neonbeleuchtete Chillout-Lounge in der Innenstadt</b>, die ein buntes Publikum von Clubgängern und Drogensüchtigen anzieht. Neben modernen Groove bietet es eine fremdartige, insektoide Einrichtung. In einem kegelförmigen Gebäude, das architektonisch an ein Termitennest erinnert, befindet sich ein Gewirr gemütlicher, verräucherter Lounges, die sich um einen gut bewachten und befestigten Kern herum gruppieren. Der Kernzylinder ist in mehrere Ebenen unterteilt, in denen sich die Waffen-, Bargeldund Drogenvorräte der Bande sowie das Grasfeld der Adze-Parasiten im Erdgeschoss befinden, wo sie sich vermehren und ihre Larven heranwachsen. Die Adze- Wirte kennen jede Gabelung und jeden Durchgang im Nest, was sie hochgradig verteidigungsfähig macht. Die Glühwürmchen-Vertrauten sind, wenn sie sich von ihren Wirten lösen, hier fast unmöglich zu fangen.","sz":9.5,"box":[309.0,78.5,540.1,287.8],"p":242,"i":8,"sec":"blutbad-in-der-innenstadt"},{"t":"sh","x":"<b>BRACHIALES VORGEHEN</b>","sz":10.0,"box":[309.4,301.4,443.9,311.4],"p":242,"i":9,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"In Unkenntnis des Adze-Parasiten und erfüllt von <t>Rachsucht 2</t> sind die Fahrenden auf einer von ihrem Anführer Beaumont angeordneten Queste, um „das Land von der Adze-Geißel zu befreien“. Was in Albion edel klingen mag, bedeutet, dass sie alle Mitglieder brutal umbringen. Diese sind in Wirklichkeit nur Süchtige, die unter dem Einfluss der Insekten stehen. Bewaffnet mit den üblichen <i>Schrottschwertern</i>, <i>Schrotflinten</i> und <i>Benzintanks</i> wollen sie tief ins Herz des Nests vordringen, es abfackeln und die Adze ein für alle Mal erledigen. Der Angriff besteht aus drei Phasen:","sz":9.5,"box":[309.0,317.0,536.0,464.0],"p":242,"i":10,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"• <b>An den Eingängen und Fenstern der Lounge kommt es zu Schüssen,</b> bei denen Passanten ins Kreuzfeuer geraten, bis die Fahrenden einbrechen;","sz":9.5,"box":[309.0,475.5,530.9,510.0],"p":242,"i":11,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"• <b>Eine Schlägerei quer durch alle Clubräume</b>, bei der die Fahrenden alle Adze-Wachen und -Betreiber, die ihnen in den Weg kommen, abschlachten, wobei es zu Verletzungen und Todesfällen unter den Gästen kommt (die in Beaumonts Augen genauso verdammt sind wie die Adze);","sz":9.5,"box":[309.0,518.7,537.7,590.7],"p":242,"i":12,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"• <b>Mit Sprengstoff in den Kernzylinder</b> (<t>befestigt 3</t>) eindringen, die letzten Mitglieder auslöschen, ihr Versteck plündern und den Club in Brand setzen.","sz":9.5,"box":[309.0,599.4,531.3,633.9],"p":242,"i":13,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"Die Barbarei als akzeptierter, integraler Bestandteil des Kampfes sollte von Anfang an erkennbar sein, und zwar auf beiden Seiten, denn die Adze-Parasiten sind leicht bereit, sich ihrer Wirte zu entledigen. Wenn die Fahrenden eindringen, wird offensichtlich, dass die einst idealistische Ritterbande nun auf einem hasserfüllten Vernichtungsfeldzug ist. Egal, ob das Team den Fahrenden hilft oder gegen sie kämpft, sorge mit einer harten Aktion (oder <b>Angriff mit Ansage</b>) an einer Schlüsselstelle dafür, dass <b>etwas Schreckliches</b>","sz":9.5,"box":[309.0,642.5,537.7,764.6],"p":242,"i":14,"sec":"blutbad-in-der-innenstadt"}],"size":[595.276,841.89]},"243":{"tab":"","blocks":[{"t":"p","x":"<b>geschied</b> und die Fahrenden ein besiegtes Mitglied der Adze-Gang, dessen Parasit geflohen ist, oder einen unglücklichen Zuschauer brutal und gefühllos töten.","sz":9.5,"box":[53.9,62.5,285.5,97.0],"p":243,"i":0,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"Während des Geschehens können bedachtsame SC <b>Nachforschungen</b> anstellen und möglicherweise Hinweise finden, um das Blutbad zu verhindern.","sz":9.5,"box":[53.9,105.7,283.8,140.2],"p":243,"i":1,"sec":"blutbad-in-der-innenstadt"},{"t":"card","x":"Jedes Mitglied der Adze-Bande hat ein <b>kleines, flimmerndes Insekt im Nacken</b>. Glühwürmchen, die normalerweise keine Menschen beißen, wie jede Zoolog:in weiß.","sz":null,"k":"yellow","box":[54.1,149.8,286.6,208.5],"p":243,"i":2,"sec":"blutbad-in-der-innenstadt"},{"t":"card","x":"Die Adze sprechen kaum und scheinen sich untereinander mit Gesten oder telepathisch zu verständigen. Ihr Verhalten lässt erkennen, <b>dass sie untereinander kommunizieren</b>.","sz":null,"k":"yellow","box":[54.1,217.7,286.6,276.8],"p":243,"i":3,"sec":"blutbad-in-der-innenstadt"},{"t":"card","x":"<b>Ein Blick jenseits des Nebels</b> oder Erkenntnismagie zeigen eine schleichende Gestalt in einem Lendenschurz, die auf dem Rücken des Wirts reitet, seine Schultern mit ihren Klauen ergreift und ihre Zähne genau dort versenkt, wo das Glühwürmchen sitzt. <b>Dieses Vampirwesen ernährt sich vom Blut des Bandenmitglieds und kontrolliert gleichzeitig seinen Geist.</b>","sz":null,"k":"yellow","box":[54.1,285.7,286.6,407.2],"p":243,"i":4,"sec":"blutbad-in-der-innenstadt"},{"t":"h","x":"RÕSHI O’KANE","sz":14.0,"box":[62.4,435.8,129.5,449.8],"p":243,"i":5,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"Der ehrwürdige, bescheidene Rōshi O’Kane, ein sanfter Zen-buddhistischer Mönch und Straßenprediger, streift in seinen braunen und orangefarbenen Gewändern durch die Straßen, auf der Suche nach gebrochenen Menschen, denen er helfen und die er emotional heilen kann. Im Augenblick ist er ein Schläfer, den spirituelles und religiöses Engagement antreibt, aber er könnte bald zu seinem Mythos erwachen, vorausgesetzt, er stirbt heute Nacht nicht.","sz":9.0,"box":[62.4,462.4,270.0,567.4],"p":243,"i":6,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"Wenn du einen moralischen Kompass brauchst, um die Aktionen der Fahrenden zu kontrastieren, kann Rōshi O’Kane auftauchen und versuchen, die Banden von Feindseligkeiten abzubringen. Er wird den Fahrenden ins Nest folgen und versuchen, sich ihnen in den Weg zu stellen. Er ist unvorsichtig, und wenn die SC nicht eingreifen, wird er dem Blutbad zum Opfer fallen. Nutze dies, um die SC zu erschüttern und sie auf ihre Moral auszurichten (falls vorhanden).","sz":9.0,"box":[62.4,576.1,271.8,681.1],"p":243,"i":7,"sec":"blutbad-in-der-innenstadt"},{"t":"card","x":"Vorahnungen oder Monstermythen deuten darauf hin, dass <b>ein Einfangen des Adze-Glühwürmchens dazu führt, dass es sich in seine humanoide Form verwandelt.</b>","sz":null,"k":"yellow","box":[309.3,54.1,541.7,112.9],"p":243,"i":8,"sec":"blutbad-in-der-innenstadt"},{"t":"card","x":"<b>Die Fahrenden haben keine Ahnung, dass die Glühwürmchen die Adze mental kontrollieren.</b> Für sie sind die Adze krimineller Abschaum, und je schneller sie sterben, desto schneller ist die Stadt diese Krankheit los.","sz":null,"k":"yellow","box":[309.3,122.1,541.7,193.5],"p":243,"i":9,"sec":"blutbad-in-der-innenstadt"},{"t":"card","x":"<b>Jenseits des Nebels</b> verwandelt sich der Mythos der galanten Ritter in glänzender Rüstung langsam in <b>blutige, kampferprobte mittelalterliche Kreuzritter</b>, die im Namen des Heiligen Krieges jeden niedermetzeln.","sz":null,"k":"yellow","box":[309.3,202.8,541.7,274.2],"p":243,"i":10,"sec":"blutbad-in-der-innenstadt"},{"t":"threat","stars":"★★","name":"ADZE-HEXE","spectra":"","items":[],"box":[375.6,306.9,396.0,318.9],"p":243,"i":11,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"Die Mitglieder der Adze-Bande, unabhängig vom Geschlecht auch „Hexen“ genannt, sind Menschen, die von einem Adze-Glühwürmchen besessen sind. Die Gangster tragen gute Sportkleidung mit fetten Goldketten oder unauffällige Jacken und Jeans, wenn sie im Verborgenen agieren. Sie verstecken ihre Vertrauten nicht, sondern tragen sie als Abzeichen, das anderen Gangs signalisiert, sich zurückzuhalten.","sz":9.0,"box":[317.5,330.0,528.6,423.0],"p":243,"i":12,"sec":"blutbad-in-der-innenstadt"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 3 / GLÜH- WÜRMCHEN ENTFERNEN 3 / EXORZIEREN 3</b>","sz":12.0,"box":[317.5,433.6,531.1,457.6],"p":243,"i":13,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"• <b>Besessen</b>: Man kann den Glühwürmchen-Vertrauten von der Adze-Hexe entfernen, wenn der Maximalwert in einem der Spektren <i>Unschädlich machen</i>, <i>Glühwürmchen entfernen</i> oder <i>Exorzieren</i> erreicht ist. Die Adze-Hexe wird dann ohnmächtig, und eine neue Bedrohung, Adze-Glühwürmchen, entsteht, die vorübergehend <t>desorientiert 2</t> ist. Der nächste Angriff kann <b>Mit aller Gewalt</b> erfolgen. • <b>Vampirische Eifersucht</b>: Verleihe der Adze-Hexe für jede Stärke und jeden Geschichten-Marker, die ihr Ziel besitzt, und die für Reichtum, Statussymbole oder gutes Aussehen stehen, <t>Raserei</t>. Dieser Zustand kann Stufe 3 nicht überschreiten.","sz":9.0,"box":[317.5,462.0,532.8,615.0],"p":243,"i":14,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"• Kurze Feuerstöße abgeben (<t>Fleischwunde 2</t>) oder jemanden mit einem Schlagring verprügeln (<t>ausgeschlagene Zähne 2</t> oder <t>desorientiert 2</t>) • Jemanden festhalten, um zu beißen (<t>festgehalten 3</t>) • Die Zähne in jemandem schlagen und der Person Blut und Kraft absaugen (die Adze-Hexe gewinnt für jede Stufe <t>festgehalten</t> 1 Stufe <t>gestärkt</t> oder verbrenne eine relevante Stärke oder Zustandsstufe)","sz":9.0,"box":[317.5,624.0,529.7,717.0],"p":243,"i":15,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"• Jemanden fixieren, der ihre Eifersucht weckt • Ihr nächstes Ziel anstarren und frech lächeln, um dann die Reißzähne entblößen","sz":9.0,"box":[317.5,726.0,522.6,759.0],"p":243,"i":16,"sec":"blutbad-in-der-innenstadt"}],"size":[595.276,841.89]},"244":{"tab":"","blocks":[{"t":"threat","stars":"★★★","name":"ADZE-GLÜHWÜRMCHEN","spectra":"","items":[],"box":[183.8,58.2,214.4,70.2],"p":244,"i":0,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"Die Adze-Glühwürmchen-Vertrauten sind die treibende Kraft hinter der Adze-Gang. Indem sie die stärksten Opfer, die sie finden, <t>besetzen</t> und sie gewaltsam in ihren Schwarm rekrutiert, kann sich die vampirische Spezies die gewünschten Ernährungsund Fortpflanzungsbedingungen in der urbanen Umgebung sichern. Die <t>besessenen</t> Opfer werden zu „Hexen“, die ihr Bewusstsein und Fähigkeiten behalten, aber durch die übermächtigen Instinkte gezwungen sind, der Adze-Gang zu dienen.","sz":9.0,"box":[62.4,81.3,275.3,198.3],"p":244,"i":1,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"Der Legende nach ist ein Adze als Glühwürmchen unzerstörbar, aber wenn man ihn fängt, ist er gezwungen, seine verletzliche Vampirgestalt zu offenbaren. Nichts kann einen Adze als Glühwürmchen abhalten, in ein Haus einzudringen und jemanden zu beißen.","sz":9.0,"box":[62.4,207.3,276.9,264.3],"p":244,"i":2,"sec":"blutbad-in-der-innenstadt"},{"t":"sh","x":"<b>VERLETZEN – / FANGEN 3</b>","sz":12.0,"box":[62.4,274.8,164.4,286.8],"p":244,"i":3,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"• <b>Gefangen verwundbar</b>: Wenn <i>Fangen 3</i> den Maximalwert erreicht, nimmt das Adze-Glühwürmchen menschliche Gestalt an. Ändere den Maximalwert bei <i>Verletzen oder unschädlich machen</i> auf 3. • <b>Alles durchdringend</b>: Es gibt keine bekannte Verteidigung gegen die Adze in ihrer Glühwürmchengestalt. Stärken, die Barrieren und Verteidigungen darstellen, sind nicht anwendbar, und das Glühwürmchen kann jedes Hindernis umgehen oder als weiche Aktion durchdringen. • <b>Vampirischer Appetit</b>: Für jede Kraft oder jeden Marker, den das Ziel des Adze-Glühwürmchens besitzt, der für Stärke, Vitalität oder magische Kraft steht, erhält des eine Stufe <t>Raserei</t>. Dieser Zustand kann Stufe 3 nicht überschreiten.","sz":9.0,"box":[62.4,291.3,276.6,468.3],"p":244,"i":4,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"• (In beiden Gestalten) sich an sein Opfer klammern und es <t>übernehmen 3</t> oder <t>aussaugen 3</t> (für jede Stufe von <t>aussaugen</t>, die nach <b>Sich der Gefahr stellen</b> verbleibt, erhält es 1 Stufe <t>gestärkt</t> oder verbrennt eine relevante Stärke oder Zustandsstufe) • (In Glühwürmchengestalt) Sich in Wände eingraben oder durch ein Fenster oder Öffnung entkommen (<b>Ihnen etwas verweigern, das sie wollen</b>)","sz":9.0,"box":[62.4,477.3,277.8,570.4],"p":244,"i":5,"sec":"blutbad-in-der-innenstadt"},{"t":"p","x":"• Im Raum umherschwirren und in einem unheimlichen grünen Licht flackern. • Sich auf seine nächste Beute stürzen","sz":9.0,"box":[62.4,579.3,266.8,612.3],"p":244,"i":6,"sec":"blutbad-in-der-innenstadt"},{"t":"h","x":"DER STEINALTAR","sz":16.0,"box":[334.8,68.9,443.9,84.9],"p":244,"i":7,"skip":true,"sec":"der-steinaltar"},{"t":"ro","x":"Die Blätter der alten Erlen, Eiben und Haselnussbäume um die Lichtung rascheln leise im böigen Wind. Bei bedecktem Himmel schleppt eine Schar der Ritter von Albion eine gebundene Person in die Mitte der Lichtung, wo ein alter, von Flechten bedeckter Dolmen im Schlamm liegt. Während die zerfetzten Banner im Wind flattern, ketten sie die Gestalt an den Altar und warten auf ihren König. Es dauert nicht lange, da erscheint er, unbeugsam und mit finsterer Miene, doch in seinen Augen brennt die Hoffnung auf den Sieg.","sz":9.0,"box":[317.5,87.3,538.9,225.9],"p":244,"i":8,"sec":"der-steinaltar"},{"t":"p","x":"Die Prophezeiung vom Questentier ist einer von Beaumonts Wegen, um magische Kraft für einen Angriff auf den König in Karmesin zu erlangen. In dieser Szene kann sich die Prophezeiung um den Preis eines Lebens erfüllen, indem man das „Questentier“ tötet, was die SC mit Beaumonts Grausamkeit konfrontiert.","sz":9.5,"box":[309.0,234.9,540.9,306.9],"p":244,"i":9,"sec":"der-steinaltar"},{"t":"p","x":"In der Stadt ist das <b>Questentier</b> keine bestimmte Person, sondern ein Titel, den alle tragen können, die verachtet oder geschmäht genug sind, sei es zu Unrecht, aufgrund von Bigotterie und Hass oder weil diese Person so abscheuliche Gräueltaten begangen hat, dass sie ihn rechtfertigt. Standardmäßig ist dies <b>Eva Rice</b>, die Immobilienmogulin und Riss des Wendigo, die zahlreiche Bewohner:innen der Stadt verschlang und dann ihr Verschwinden nutzte, um Häuser und ganze Viertel zu übernehmen (s. S. <i>Daheim ist daheim</i>, S. 209). Andere Alternativen sind eine ältere Matrone der Adze-Bande (die man fälschlicherweise für die Anführerin hält) oder der arme Archie, den alle hassen, weil er ein Drache ist (s. S. <i>Albion erwache!</i>, S. 195). <b>Das Questentier kann jeder SC oder NSC deiner Serie sein</b>, einschließlich verhasster Erzbösewicht:innen, einer Nemesis, Nebenfiguren, die vom rechten Weg abgekommen sind usw. – je dramatischer, desto besser.","sz":9.5,"box":[309.0,315.5,541.3,550.0],"p":244,"i":10,"sec":"der-steinaltar"},{"t":"p","x":"<b>In dieser Szene nimmt das Team an der Tötung (sprich: Hinrichtung) der Bestie als Questentier teil oder mischt sich ein</b>. Die Rolle der SC kann von Spielverderber:innen über Beobachtende bis hin zu ihren Jäger:innen oder schließlich Henker:innen reichen. Wenn die SC mit Beaumont im Bunde sind, prüft er, was sie zu tun bereit sind. Er könnte sie drängen, eine aktivere Rolle zu übernehmen, um festzustellen, ob er ihnen zutrauen kann, Skrupel und Moral für das ultimative Ziel, den König in Karmesin zu besiegen, beiseitezuschieben.","sz":9.5,"box":[309.0,558.8,538.5,693.2],"p":244,"i":11,"sec":"der-steinaltar"}],"size":[595.276,841.89]},"245":{"tab":"","blocks":[{"t":"sh","x":"<b>DAS RITUAL</b>","sz":10.0,"box":[54.3,381.0,120.7,391.0],"p":245,"i":0,"sec":"der-steinaltar"},{"t":"p","x":"<b>Die Häscher bringen das Questentier zu einem Steinaltar auf einer Lichtung in Albion.</b> Dort müssen entweder ein SC, Beaumont oder einer der Fahrenden es töten. Für Beaumont und die Fahrenden gibt es zwei Argumente, um die Hinrichtung durchzuführen, mit denen sie das Team überzeugen können:","sz":9.5,"box":[53.9,396.6,284.5,468.5],"p":245,"i":1,"sec":"der-steinaltar"},{"t":"p","x":"• Das Questentier ist eine unausrottbare Abscheulichkeit, die den Tod verdient.","sz":9.5,"box":[53.9,480.0,283.8,502.0],"p":245,"i":2,"sec":"der-steinaltar"},{"t":"p","x":"• Der Tod des Questentiers ist die einzige Möglichkeit, Albion die Macht zu geben, seinen Feind und den der ganzen Stadt zu vernichten – den König in Karmesin.","sz":9.5,"box":[53.9,510.7,286.0,545.2],"p":245,"i":3,"sec":"der-steinaltar"},{"t":"p","x":"<b>Nachforschungen</b> über den Wahnsinn, der Beaumont und seine Bande in dieser Szene überfällt, ergibt die gleichen Hinweise wie in <u>Camelot.</u>","sz":9.5,"box":[53.9,556.7,282.1,591.2],"p":245,"i":4,"sec":"der-steinaltar"},{"t":"p","x":"Wenn das Team von den moralischen Implikationen der Hinrichtung unbeeindruckt ist, bring ein moralisches Gegengewicht ins Spiel, z. B. eine Nebenrolle, einen Mentor oder einen anderen NSC. Optionen sind:","sz":9.5,"box":[53.9,599.9,283.6,646.9],"p":245,"i":5,"sec":"der-steinaltar"},{"t":"p","x":"• <b>Céline Rowland</b> (Herrin vom See), die eine kryptische Warnung ausspricht, dass man die Prophezeiung verschieden interpretieren kann und die Art ihrer Interpretation die Wirkung bestimmen wird","sz":9.5,"box":[53.9,658.4,278.7,705.4],"p":245,"i":6,"sec":"der-steinaltar"},{"t":"p","x":"• Der <b>Mönch Rōshi O’Kane</b>, der hierher gewandert ist, um Beaumont von seinem Verhalten abzubringen","sz":9.5,"box":[53.9,714.0,286.0,736.0],"p":245,"i":7,"sec":"der-steinaltar"},{"t":"p","x":"• Die <b>Journalistin Reiko Ikeda</b>, die über das Ereignis aus dem Schatten berichtet, mischt sich ein","sz":9.5,"box":[53.9,744.7,281.2,766.7],"p":245,"i":8,"sec":"der-steinaltar"},{"t":"card","x":"<b>Wenn man Céline Rowlands Einspruch bemerkt,</b> können gute Menschenkenner:innen begreifen, dass sie <b>eigene Gründe hat, sich dem Ritual zu widersetzen</b>. Sie macht sich Gedanken darüber, was Beaumont tun würde, wenn er die Superwaffe findet – wegen der Bedrohung für die Stadt, aber auch, weil sie jemanden schützt. Es wird nicht einfach, sie aufzuspüren (s. S. ihr Bedrohungsprofil auf S. 252), aber sie kann das Team zu <u>Ray Gibbons’ Junggesellenbude</u> führen.","sz":null,"k":"yellow","box":[309.3,372.4,541.7,518.7],"p":245,"i":9,"sec":"der-steinaltar"},{"t":"p","x":"Wenn SC im Begriff sind, das Questentier zu töten, gib ihnen eine letzte Beschreibung der Verwundbarkeit und der ultimativen Menschlichkeit der Missgeburt und <b>Stelle sie vor die Wahl</b>.","sz":9.5,"box":[309.0,531.2,537.6,578.3],"p":245,"i":10,"sec":"der-steinaltar"},{"t":"sh","x":"<b>DAS ERGEBNIS</b>","sz":10.0,"box":[309.4,591.8,388.9,601.8],"p":245,"i":11,"sec":"der-steinaltar"},{"t":"p","x":"<b>Wenn die SC sich widersetzen und die Hinrichtung erfolgreich abwenden,</b> sieht Beaumont dies als Hochverrat an. Wenn die SC einen Status in Albion hatten, verlieren sie ihn und werden <t>als Verräter gebrandmarkt 5</t>. Beaumont und die Fahrenden greifen brutal an.","sz":9.5,"box":[309.0,607.5,541.2,679.4],"p":245,"i":12,"sec":"der-steinaltar"},{"t":"p","x":"<b>Wenn die Hinrichtung stattfindet</b>, weht ein mächtiger magischer Windstoß von dem blutverschmierten Altar in alle Richtungen, und ein donnernder Schrei ertönt in ganz Albion. Die Queste ist abgeschlossen, die dadurch entfesselte Macht ist in Albion gespeichert, wie Arkanist:innen spüren. Diese Macht kann sich in Form des Erwachens von <b>Ray Gibbons</b> (Merlin)","sz":9.5,"box":[309.0,688.0,539.3,772.7],"p":245,"i":13,"sec":"der-steinaltar"}],"size":[595.276,841.89]},"246":{"tab":"","blocks":[{"t":"p","x":"und einer Vision manifestieren, die den König und die Ritter von Albion zu ihm führt <u>(Ray Gibbons’ Junggesellenbude),</u> sie kann aber auch zum Antrieb jeder Superwaffe dienen, die Beaumont erhält. Wenn die SC noch Beaumonts Genoss:innen sind, kann er sie mit der Aufgabe betrauen, Gibbons nach Albion zu bringen. Falls einige SC die geringsten Bedenken haben, sollten sie einen entsprechenden Zustand erhalten, z. B. <t>desillusioniert 2</t>, <t>Schuldgefühle 3</t> oder <t>entsetzt 4</t>.","sz":9.5,"box":[53.9,59.9,280.9,169.4],"p":246,"i":0,"sec":"der-steinaltar"},{"t":"p","x":"<b>Wenn ein SC, der die Hinrichtung unterstützt oder sich gar verpflichtet, sie durchzuführen, im letzten Moment bereut</b>, erfüllt sich die Prophezeiung auf eine andere Weise. Die Macht der Prophezeiung überträgt sich auf den SC statt auf Albion, und nur er entscheidet, was er damit tun will. Wenn sich die Macht als Vision von Ray Gibbons und seine Erweckung manifestiert, erhält nur dieser SC die Vision, und nur er kann den Mythos Merlins wecken. Was immer die Macht sein mag, der SC wird zum Hauptbestandteil der Superwaffe, die Beaumont verzweifelt will.","sz":9.5,"box":[53.9,178.2,285.6,312.6],"p":246,"i":1,"sec":"der-steinaltar"},{"t":"h","x":"CAMELOT","sz":16.0,"box":[79.7,329.3,144.9,345.3],"p":246,"i":2,"skip":true,"sec":"camelot"},{"t":"ro","x":"Von der Fassade des 63. Reviers ist nicht mehr viel übrig, was an das Gebäude erinnern könnte, auf dessen Trümmern sich dieses „Camelot“ erhebt, aber ihr könnt es noch sehen, wenn ihr die Augen zusammenkneift. Seit ihr das letzte Mal hier wart, sind aus dem Dach graue Steinbrüstungen und spitze Türme gewachsen, von denen bunte Fahnen im Wind flattern. Die abgerundeten Eingangstüren, die einst aus Glas waren, sind jetzt ein schweres Fallgatter. Seit die Fahrenden in der Stadt Fuß gefasst haben, ist viel Wasser unter der Zugbrücke hindurchgeflossen, und was als rebellische Bande begann, entwickelt sich zu einer neuen Gesellschaftsordnung – vielleicht sogar zu einem Ersatz für die bestehende? Es bleibt abzuwarten, ob Camelot der legendäre Sitz eines weisen Herrschers wird oder nur den Zweck aller Festungen erfüllt: Krieg zu führen.","sz":9.0,"box":[62.4,347.7,283.8,572.7],"p":246,"i":3,"sec":"camelot"},{"t":"p","x":"Camelot ist das Machtzentrum der Enklave Albion und das Hauptquartier von Beaumonts Fahrenden, die in der ganzen Stadt als Whitecliff-Syndikat berüchtigt sind. Die genauen Umstände dort und seine Zustand hängen von den Handlungen der SC in früheren Fällen und davon, wie sie die Enklave beeinflusst haben, ab (s. S. Der Zustand Albions, S. 234). Meistens ist Camelot in Whitecliff durch Umwandlung des 63. Polizeireviers entstanden.","sz":9.5,"box":[53.9,581.7,286.2,691.2],"p":246,"i":4,"sec":"camelot"},{"t":"p","x":"Je nach ihrer Beziehung zu Beaumont können Teammitglieder als feindliche Spion:innen oder als willkommene Reck:innen ankommen. So oder so erhalten sie die gleichen Hinweise auf Beaumonts zunehmende Besessenheit, den König in Karmesin zu besiegen.","sz":9.5,"box":[53.9,699.8,283.0,759.3],"p":246,"i":5,"sec":"camelot"},{"t":"sh","x":"<b>CAMELOTS SICHERHEIT</b>","sz":10.0,"box":[309.4,62.8,440.4,72.8],"p":246,"i":6,"sec":"camelot"},{"t":"p","x":"Wenn Camelot ein belagertes Schloss ist, dessen Existenz am seidenen Faden hängt, kann sich seine Wachmannschaft auf Beaumont selbst, die Fahrenden und Mister Barlow beschränken. Ist die Enklave zu einer beeindruckenden lokalen Supermacht geworden, könnte sie legendäre militärische Einrichtungen wie einen Greifenhort, eine Schmiede für legendäre Waffen (unter Leitung Roxies, S. 197), oder eine kleine Armee von Lanzelot-Modell II-Kriegsgolems (s. S. 206) umfassen. Füge den jeweiligen Bedrohungen-Profilen die passenden Geschichten-Marker hinzu, z. B. ein <i>Greifenross</i> für die Fahrenden oder Lanzelot.","sz":9.5,"box":[309.0,78.3,541.4,237.8],"p":246,"i":7,"sec":"camelot"},{"t":"card","x":"und/oder ein <i>Magisches Schwert Modell-II-Modifikationen</i> für","sz":null,"k":"yellow","box":[362.6,214.8,490.2,237.6],"p":246,"i":8,"sec":"camelot"},{"t":"p","x":"Patrouillen aus Fahrenden bewachen die Burg rund um die Uhr. Türen und Tore sind <t>verriegelt 2</t>. Darüber hinaus ist das Schloss <t>von Avalon gesegnet 3</t>, ein Werk Céline Rowlands (Herrin vom See). Diese Segnung schützt die Burg vor magischen Kräften von außen, einschließlich Ausspähungsmagie.","sz":9.5,"box":[309.0,246.5,532.8,318.5],"p":246,"i":9,"sec":"camelot"},{"t":"p","x":"Wenn die SC Beaumonts Verbündete sind, kann er erlauben, sich frei in der Burg zu bewegen, wird sie aber durch seinen Spion, Mister Barlow, im Auge behalten.","sz":9.5,"box":[309.0,327.2,535.0,361.7],"p":246,"i":10,"sec":"camelot"},{"t":"sh","x":"<b>NACHFORSCHUNGEN IN CAMELOT</b>","sz":10.0,"box":[309.4,375.3,497.1,385.3],"p":246,"i":11,"sec":"camelot"},{"t":"p","x":"Die folgenden Hinweise kann das Team in Gesprächen mit Fahrenden oder Diener:innen in der Burg erhalten. Es kann spionieren, physische oder mystische Beweise in der Umgebung entdecken oder Beaumont selbst beschatten, sich mit ihm unterhalten oder gegen ihn stellen.","sz":9.5,"box":[309.0,390.8,540.5,462.8],"p":246,"i":12,"sec":"camelot"},{"t":"card","x":"<b>Beaumont ist zunehmend mit dem Krieg gegen den König in Karmesin und dessen Dienern in der Stadt beschäftigt.</b> Die Einheimischen rechtfertigen sein rüdes, aggressives und grausames Verhalten damit, der Krieg habe „seinen Tribut gefordert“. In Wahrheit fragen sich viele, ob ihm Albion noch etwas bedeutet, außer als Mittel, um Krieg zu führen. Die Motivation für Beaumonts Krieg mit dem König in Karmesin scheint persönlicher Natur zu sein, aber die Hintergründe sind unklar, und Beaumont besteht darauf, für die Befreiung der Stadt zu kämpfen.","sz":null,"k":"yellow","box":[309.3,470.9,541.7,642.2],"p":246,"i":13,"sec":"camelot"},{"t":"card","x":"<b>Beaumont ist auf der Suche nach einer Superwaffe,</b> die den Krieg beenden wird. Er weiß nicht, wie er sie einsetzen wird, aber ihr gilt seine ganze Aufmerksamkeit.","sz":null,"k":"yellow","box":[309.3,651.5,541.7,710.2],"p":246,"i":14,"sec":"camelot"}],"size":[595.276,841.89]},"247":{"tab":"","blocks":[{"t":"card","x":"(Vor der Tötung des Questentiers) Er verlässt sich auf eine <b>uralte Prophezeiung, die den Weg zu einer Superwaffe offenbaren soll</b> und mit einem geheimen Ritual am Steinaltar zu tun hat.","sz":null,"k":"yellow","box":[54.1,54.1,286.6,125.6],"p":247,"i":0,"sec":"camelot"},{"t":"card","x":"(Wenn das Questentier tot ist) Der König hat eine Vision von <b>der Person, die den Verlauf des Krieges ändern könnte, einem Teenager namens Ray Gibbons</b>, der in Miller’s Square <u>(Ray Gibbons’ Junggesellenbude)</u> lebt. Offenbar zeigte die Vision, dass Gibbons in Albion zum größten aller Zauberer (Merlin) erwachen würde. Beaumont hofft, dass dies die Waffe ist, die er braucht, um das Blatt zu Albions Gunsten zu wenden.","sz":null,"k":"yellow","box":[54.1,134.8,286.6,268.4],"p":247,"i":1,"sec":"camelot"},{"t":"card","x":"<b>Man kann Beaumont nicht aufhalten, indem man ihn ermordet. Wenn man ihn einsperrt, hat das keinen Einfluss auf die Enklave.</b> Dies lässt sich erkennen, wenn Beaumont seit der ersten Begegnung mit dem Team reinkarniert ist, aber auch durch das Studium seines Mythos durch <b>Blick jenseits des Nebels</b>.","sz":null,"k":"yellow","box":[54.1,277.6,286.6,374.1],"p":247,"i":2,"sec":"camelot"},{"t":"card","x":"<b>Um Beaumonts Reinkarnation zu verhindern, muss man verstehen, warum es passiert</b> (wegen der Nimmer heilenden Wunde, der Verletzung durch Corbin Payne). Beaumont wird versuchen, dies mit der Aktion <b>monolithisch</b> und anderen Mitteln zu verbergen.","sz":null,"k":"yellow","box":[54.1,383.0,286.6,466.8],"p":247,"i":3,"sec":"camelot"},{"t":"card","x":"<b>Um Beaumonts Motivation oder die Quelle seiner Macht zu verstehen</b> (was ein und dasselbe ist, aber das ist nicht klar), muss das Team sich ihm stellen, die Hilfe von jemandem suchen, der ihn kennt, oder eine mächtige Mystiker:in konsultieren <u>(Das Geheimnis des Königs).</u> Die naheliegende Wahl ist <b>Céline Rowland</b>, Beaumonts Beraterin, die in <u>Ray Gibbons’ Junggesellenbude</u> zu finden ist (s. S. ihr Bedrohungsprofil, S. 252).","sz":null,"k":"yellow","box":[54.1,476.1,286.6,610.0],"p":247,"i":4,"sec":"camelot"},{"t":"h","x":"SCHICHT 2:","sz":14.0,"box":[309.0,61.9,377.3,75.9],"p":247,"i":5,"skip":true,"sec":"schicht-2-ausbruch-des-krieges"},{"t":"h","x":"AUSBRUCH DES KRIEGES","sz":23.0,"box":[309.0,84.2,539.6,107.2],"p":247,"i":6,"skip":true},{"t":"p","x":"Zu Beginn von Schicht 2 nimmt das Erzähltempo zu, und der Fall entwickelt sich zu einem Wettlauf mit der Zeit. Auf der einen Seite starten die Polizei und die Torwächter:innen einen Angriff auf Albion <u>(Schlacht an der Calmann-Brücke),</u> und auf der anderen Seite nähert sich Beaumont seiner Superwaffe <u>(Ray Gibbons’ Junggesellenbude).</u> Währenddessen versucht das Team, Beaumonts wahre Motive und das Geheimnis seiner Reinkarnation zu ergründen.","sz":13.0,"box":[309.0,115.1,539.7,287.6],"p":247,"i":7,"sec":"schicht-2-ausbruch-des-krieges"},{"t":"p","x":"Von nun an tickt die Uhr, Drehpausen sind rar, und die SC müssen schnell schwere Entscheidungen treffen. Die Entscheidung, einen Schauplatz zu besuchen, kann bedeuten, dass die SC die Chance verlieren, das Geschehen an einem anderen zu beeinflussen.","sz":9.5,"box":[309.0,298.2,540.9,357.7],"p":247,"i":8,"sec":"schicht-2-ausbruch-des-krieges"},{"t":"p","x":"Beschreibe die Skyline der Stadt, in der es von Polizei- und Nachrichtenhubschraubern nur so wimmelt, das Geschnatter auf allen Funkfrequenzen und die nächtlichen Straßen, die in langen Lichtschlieren von karmesinroten Bremslichtern und azurblauem Xenon-Scheinwerferlicht erstrahlen. Eine entscheidende Nacht in der Geschichte der Stadt ist angebrochen.","sz":9.5,"box":[309.0,366.3,537.0,450.8],"p":247,"i":9,"sec":"schicht-2-ausbruch-des-krieges"},{"t":"h","x":"DAS GEHEIMNIS DES KÖNIGS","sz":16.0,"box":[334.8,467.5,525.3,483.5],"p":247,"i":10,"skip":true,"sec":"das-geheimnis-des-koenigs"},{"t":"p","x":"In dieser Schicht kann das Team enthüllen, <b>dass Vince Beaumont ein Gralsritter ist</b>, der unwissentlich in Diensten des Königs in Karmesin steht.","sz":9.5,"box":[309.0,487.4,540.5,521.9],"p":247,"i":11,"sec":"das-geheimnis-des-koenigs"},{"t":"p","x":"Diese Information kann Céline Rowland liefern, wenn das Team ihr hilft, die Rekrutierung ihres Sohnes Ray Gibbons zu verhindern <u>(Ray Gibbons’ Junggesellenbude).</u> Mutige SC können versuchen, die Informationen direkt vom König zu erhalten, indem sie sich ihm stellen, wenn es ihnen gelingt, die Abwehrmechanismen von <b>Avalonischer Zauber</b> und <b>monolithisch</b> zu umgehen. Zum Leidwesen des Teams bewahrt der er keine physischen Beweise für seine früheren Leben auf.","sz":9.5,"box":[309.0,530.6,540.1,640.1],"p":247,"i":12,"sec":"das-geheimnis-des-koenigs"},{"t":"p","x":"Alternativ kann das Team – gegen eine Gebühr – einen der folgenden Mystiker:innen in der Stadt konsultieren und die gleichen Informationen erhalten.","sz":9.5,"box":[309.0,648.8,541.4,683.3],"p":247,"i":13,"sec":"das-geheimnis-des-koenigs"},{"t":"p","x":"• <b>Destiny Melancon</b> (Maman Brigitte, haitianische Voodoo-Loa des Todes und Gefährtin Baron Samedis) betreibt <b>Destiny Melancons Haus der Wahrsagerei</b>. In einem billigen, mit lila Samt ausgeschlagenen und von magentafarbenem Neon beleuchteten Hinterzimmer bietet sie Séancen, Handlesen,","sz":9.5,"box":[309.0,694.8,540.6,766.8],"p":247,"i":14,"sec":"das-geheimnis-des-koenigs"}],"size":[595.276,841.89]},"248":{"tab":"","blocks":[{"t":"p","x":"Kristallkugelschau und Tarot-Legungen an. Destiny ist eine der qualifiziertesten Hellseher:innen in der Stadt, wenn es darum geht, Fragen zum Tod, zum Leben danach und zu Reinkarnationen zu beantworten. Sie lässt sich in Rum mit Chili bezahlen, braucht aber einen Gegenstand, der Beaumont gehört, um seine Seele zu verfolgen. Destiny arbeitet auch für <b>Samuel Valtierra</b> (Baron Samedi), einen mit Beaumont verfeindeten Verbrecher, der Albion vernichtet sehen will und als Bedingung für Melancons Dienste die Kooperation der SC verlangen könnte.","sz":9.5,"box":[62.4,59.9,284.7,194.4],"p":248,"i":0,"sec":"das-geheimnis-des-koenigs"},{"t":"p","x":"• Der Bibliothekar <b>Fadi Malek</b> (Thoth, s. <i>Parzival</i>, S. 270) wird nur ungern Informationen über die persönliche Reinkarnation mit den SC teilen, die einen Weg finden müssen, ihn zu überreden oder stattdessen sein <i>Totenbuch</i> zu stehlen.","sz":9.5,"box":[53.9,203.1,282.2,262.6],"p":248,"i":1,"sec":"das-geheimnis-des-koenigs"},{"t":"p","x":"• In der <b>Tiki-Bar „Sacred Land“</b> können die Besitzerin <b>Ailani Jack</b> und ihre ungeborenen weisen Embryos (Madame Pele und Hi’iaka) arkanes Wissen für den Preis von Blut (kein ganzes Leben) geben.","sz":9.5,"box":[53.9,271.3,282.7,318.3],"p":248,"i":2,"sec":"das-geheimnis-des-koenigs"},{"t":"card","x":"<b>Vince Beaumont hat ein Kind an den König in Karmesin verloren</b>, an dessen Namen er sich wegen des Nebels nicht mehr erinnert.","sz":null,"k":"yellow","box":[54.1,335.5,286.6,381.9],"p":248,"i":3,"sec":"das-geheimnis-des-koenigs"},{"t":"p","x":"Tatsächlich erinnert sich niemand mehr an dieses Kind. Die einzige Erinnerung an sie ist in Beaumonts Trauer verankert. (Dies könnte auf den dritten und letzten Akt von <i>Parzival</i>, den übergreifenden Fall, S. 281, hinweisen).","sz":10.0,"box":[62.4,396.6,268.2,456.6],"p":248,"i":4,"sec":"das-geheimnis-des-koenigs"},{"t":"card","x":"<b>Der König in Karmesin, Herr der Schmerzen, konnte Vince Beaumonts Trauer mit seiner Magie infizieren</b> und zu einem infernalischen Zorn verstärken. Er nutzt Beaumonts Zorn, um die ganze Stadt leiden und bluten zu lassen. Mit anderen Worten: <b>Beaumont ist ein Spielball in den Händen seines Widersachers.</b>","sz":null,"k":"yellow","box":[54.1,471.5,286.6,567.9],"p":248,"i":5,"sec":"das-geheimnis-des-koenigs"},{"t":"card","x":"<b>Beaumont kann dank einer Synergie aus seinem Mythos und der Wunde, die ihm der König in Karmesin zugefügt hat, reinkarnieren.</b> Der Mythos von Artus, dem „König von Camelot“, erlaubt es seinen Rissen, die Erinnerungen an vergangene Reinkarnationen zu bewahren. Vince Beaumonts korrumpierter Schmerz überträgt sich von einer Inkarnation auf die nächste und übernimmt sie, so dass sie auf diesen Schmerz nur noch mit dem Kampf gegen den König in Karmesin reagieren. Das gilt für alle Reinkarnationen, denen das Team begegnet ist: Calvin Cyrus, MoniqueR usw.","sz":null,"k":"yellow","box":[54.1,576.9,286.6,748.2],"p":248,"i":6,"sec":"das-geheimnis-des-koenigs"},{"t":"p","x":"Wenn das Team im Corbin Tower war (s. S. <i>Parzival</i>, S. 273) und die Vision von Vince Beaumont, der Corbin Payne tötet, gesehen hat, kann es ihn nun als den namenlosen Mann in dieser Vision identifizieren.","sz":10.0,"box":[317.5,60.3,524.1,120.3],"p":248,"i":7,"sec":"das-geheimnis-des-koenigs"},{"t":"h","x":"SCHLACHT AN DER CALMANN-BRÜCKE","sz":16.0,"box":[333.1,147.8,462.2,180.8],"p":248,"i":8,"skip":true,"sec":"schlacht-an-der-calmann-bruecke"},{"t":"ro","x":"Mannschaftswagen der Polizei, gepanzerte SWAT-Fahrzeuge und Truppentransporter fahren vor den Barrikaden von Whitecliff vor, die wie eine bedrohliche mittelalterliche Mauer aussehen, während die Fanfaren des Königreichs Alarm geben. Gerade als man denkt, die Ordnungskräfte hätten die letzten Truppen aufgefahren, übertönt das laute Geräusch über Beton rollenden Metalls alles andere, und die Polizist:innen und Soldat:innen treten zur Seite, um einen Panzerkonvoi durchzulassen. Am Himmel liefern sich Polizeihubschrauber ein Feuergefecht mit einem Flugtier mit Falkenkopf. Die Erde bebt, als der Panzer feuert, aber sein erster Schuss trifft nicht die Mauer. Als sich der Rauch lichtet, sieht man einen eisernen Riesen aus Schrott und Trümmern mit einem klaffenden, verkohlten Loch in der Brust zu Boden sinken. Dann brüllen die Armeen und gehen zum Angriff über. Der letzte Akt des Krieges hat begonnen.","sz":9.0,"box":[317.5,183.2,538.9,429.8],"p":248,"i":9,"sec":"schlacht-an-der-calmann-bruecke"},{"t":"p","x":"Irgendwann während des Kriegs wackelt die Pattsituation, und die städtischen Ordnungskräfte und Torwächter:innen müssen einen Angriff auf die Enklave Albion riskieren, um zu sehen, ob sie sie einnehmen und versiegeln können. Dies gilt vor allem dann, wenn das <u>Blutbad in der Innenstadt</u> eine öffentliche Panik ausgelöst hat oder wenn Beaumont nach dem Ritual am <u>Steinaltar</u> auf dem Weg ist, seine Superwaffe zu erlangen, und erst recht, wenn Abgesandte (SC oder NSC) <u>Ray Gibbons’ Junggesellenbude</u> gefunden haben.","sz":9.5,"box":[309.0,438.8,538.2,560.8],"p":248,"i":10,"sec":"schlacht-an-der-calmann-bruecke"},{"t":"sh","x":"<b>DIE ROLLE DES TEAMS</b>","sz":10.0,"box":[309.4,574.4,432.3,584.4],"p":248,"i":11,"sec":"schlacht-an-der-calmann-bruecke"},{"t":"p","x":"Wenn die SC die Grenze nicht aktiv beobachten, überrascht die Szene sie mitten in dem, woran sie arbeiten. Während des Angriffs müssen sie sich entscheiden, ob sie den Kampf abwarten – in dem Fall dringen Polizei und Torwächter:innen über die Grenze vor und bahnen sich ihren Weg durch Albion nach Camelot – oder eingreifen und den Ausgang in die eine oder andere Richtung lenken. Sie können eingreifen oder versuchen, zu <u>Ray Gibbons’ Junggesellenbude</u> zu eilen und ihn auf ihre Seite zu ziehen (s. S. <u>Ray Gibbons,</u> S. 252).","sz":9.5,"box":[309.0,589.9,540.7,711.9],"p":248,"i":12,"sec":"schlacht-an-der-calmann-bruecke"},{"t":"p","x":"<b>Ehe die Spieler:innen eine Entscheidung treffen, lege ihnen die Konsequenzen dar und frag sie, was ihre SC fühlen, wenn sie die Aussichten auf einen Sieg der einen oder anderen Seite bedenken.</b> Denk daran, dass keine Seite schuldlos ist:","sz":9.5,"box":[309.0,720.7,538.1,780.1],"p":248,"i":13,"sec":"schlacht-an-der-calmann-bruecke"}],"size":[595.276,841.89]},"249":{"tab":"","blocks":[{"t":"p","x":"Beaumont entpuppt sich als durchgeknallter Kriegsherr, der nicht weiß, wann er aufhören muss zu kämpfen. Die Polizei und die Torwächter:innen hingegen werden kurzen Prozess mit der schönen Enklave Albion machen und wahrscheinlich versuchen, die Erinnerungen des Teams zu löschen, egal was Lars Erikson sagt. <b>Verstärke das Dilemma für deine Spieler:innen, indem du die Fehler der Seite betonst, der sie gerade dienen oder der zu helfen sie geneigt sind.</b>","sz":9.5,"box":[53.9,380.2,282.3,489.9],"p":249,"i":0,"sec":"schlacht-an-der-calmann-bruecke"},{"t":"sh","x":"<b>DIE KAMPFZONE</b>","sz":10.0,"box":[54.3,503.3,145.9,513.3],"p":249,"i":1,"sec":"schlacht-an-der-calmann-bruecke"},{"t":"p","x":"Der Kampf findet auf einer Brücke über die Autobahn statt, die Albion vom Rest der Stadt trennt. Beide Seiten setzen die unter <u>Die Grenzlande</u> (s. S. 237) aufgeführten Patrouillen, Truppen und noch stärkere Einheiten und Waffen ein (s. u.)","sz":9.5,"box":[53.9,518.9,278.3,578.4],"p":249,"i":2,"sec":"schlacht-an-der-calmann-bruecke"},{"t":"p","x":"<b>DAS HEER VON ALBION</b> hat zwei Verteidigungslinien auf der Brücke errichtet: <b>eine Mauer</b> und eine Frontlinie aus zwei <b>Barrikaden</b>, beide eine Mischung aus einer mittelalterlichen Ziegelmauer und Schrottautos, Metallzäunen, Stacheldraht usw. Diese Schrottplatzbefestigungen von Albion sind das Werk der legendären Schmiedin Roxie (s. S. 197) und daher viel haltbarer, als sie scheinen. Etwas weiter von der Brücke entfernt steht das <b>Kommandozelt</b>, das mit bunten Bannern geschmückt ist. Dorthin kommt Beaumont, um die Schlacht zu leiten, es sei denn, er hat Dringenderes zu tun <u>(Ray Gibbons’ Junggesellenbude).</u> Je nach den cineastischen Überlegungen kann das Heer von Albion mit einigen der folgenden Überraschungen aufwarten:","sz":9.5,"box":[53.9,587.1,286.1,771.6],"p":249,"i":3,"sec":"schlacht-an-der-calmann-bruecke"},{"t":"p","x":"• <b>Katapulte</b> auf einem nahegelegenen Parkplatz sorgen für Artillerieunterstützung. • <b>Minen auf der Brücke</b> können ein letztes Mittel sein, um den Angriff zu verlangsamen. • Céline Rowland kann <b>den Tunnel</b>, eine Stelle in der Nähe, wo der Nebel dünn ist, nutzen, um Verstärkung herbeizuschaffen oder einen Fluchtweg öffnen, wenn die Schlacht verloren ist. • <b>Lanzelot-Modell II-Kriegsgolem</b>s oder <b>Trolle</b> aus den Wäldern Albions können den Feind angreifen. • <b>Greifenreiter:innen</b> können alle Luftstreitkräfte abfangen, die versuchen, die Grenze zu überschreiten.","sz":9.5,"box":[309.0,382.8,541.4,529.8],"p":249,"i":4,"sec":"schlacht-an-der-calmann-bruecke"},{"t":"p","x":"<b>DIE ORDNUNGSKRÄFTE DER STADT</b> haben sich wegen des steilen Hügels, der ihnen eine <i>Überlegene Position</i> sichert, für die Calmann-Brücke entschieden. Er begrenzt den Zugang zu zwei Straßen im Norden und Westen. Das <b>Front-HQ</b> ist in einem an die Hauptkonfliktzone angrenzenden Gebäude eingerichtet, wo mehrere Polizeiautos und ein SUV der Spezialeinheiten geparkt sind. Zu diesen Spezialeinheiten gehören unter anderem:","sz":9.5,"box":[309.0,541.3,536.8,650.8],"p":249,"i":5,"sec":"schlacht-an-der-calmann-bruecke"},{"t":"p","x":"• <b>Scharfschütz:innen</b> der Polizei auf den Dächern und Felskuppen • <b>Panzer der Armee</b>, die die weltliche Feuerkraft bereitstellen, um die magischen Mauern Albions zu durchbrechen • Ein <b>Geschützturm oder Panzer</b> auf der südlichen Klippe, der Artillerieunterstützung gewährleistet","sz":9.5,"box":[309.0,656.6,534.0,741.1],"p":249,"i":6,"sec":"schlacht-an-der-calmann-bruecke"}],"size":[595.276,841.89]},"250":{"tab":"","blocks":[{"t":"p","x":"Man beachte, dass die <b>Torwächter:innen</b> in Albion mit einem Nachteil kämpfen. Der Nebel ist dort so dünn, dass sie <b>Nebelbaken</b> einsetzen müssen, um ihn zu verstärken, sonst sind ihre Bedrohungseffekte um 1 reduziert. Sie dienen als Verteidigungslinie auf der Seite der Stadt und unterstützen dort. Wenn es schlecht für die Stadt aussieht, starten sie trotz ihrer geschwächten Nebel-Fähigkeiten einen rückhaltlosen Selbstmordangriff. Diese Schwäche ist der Grund, warum es Leute wie Lars Erikson gibt. Seine Rolle besteht darin, sympathisierende Risse wie vielleicht das Team zu rekrutieren, um abtrünnige Risse wie das Whitecliff-Syndikat einzudämmen.","sz":9.5,"box":[53.9,59.9,283.3,219.4],"p":250,"i":0,"sec":"schlacht-an-der-calmann-bruecke"},{"t":"p","x":"Kurz nach Ausbruch der Schlacht bricht die Barriere des Gazevorhangs zusammen, da sie dem heftigen Aufeinanderprall von Legendären und Gewöhnlichen nicht standhalten kann. Die Torwächter:innen, die dafür verantwortlich sind, Schläfer:innen ahnungslos zu halten, ziehen sich zurück und stellen die Brücke unter Quarantäne, um den Zugang zum Schlachtfeld einzuschränken.","sz":9.5,"box":[53.9,228.1,278.5,325.1],"p":250,"i":1,"sec":"schlacht-an-der-calmann-bruecke"},{"t":"card","x":"Das, was das Legendäre in der Stadt versteckt (der Nebel), steht kurz vor dem Zusammenbruch. <b>Wenn die Kampfhandlungen nicht aufhören, könnte die ganze Stadt legendären Kräften ausgesetzt werden</b> <u>(Risse allüberall).</u>","sz":null,"k":"yellow","box":[309.3,54.1,541.7,125.6],"p":250,"i":2,"sec":"schlacht-an-der-calmann-bruecke"},{"t":"sh","x":"<b>NACHWEHEN DER KAMPFHANDLUNGEN</b>","sz":10.0,"box":[309.4,142.1,529.1,152.1],"p":250,"i":3,"sec":"schlacht-an-der-calmann-bruecke"},{"t":"p","x":"Einige Zeit nach der Schlacht und unabhängig davon, wer gewonnen hat, scheint die Luft auf dem rauchenden, zerstörten Schlachtfeld zu flimmern. Bald darauf bilden sich leuchtende, neonfarbene Risse, während der Nebel in sich zusammenbricht und Mythen hereinfluten <u>(Risse allüberall).</u>","sz":9.5,"box":[309.0,157.7,540.1,229.7],"p":250,"i":4,"sec":"schlacht-an-der-calmann-bruecke"}],"size":[595.276,841.89]},"251":{"tab":"","blocks":[{"t":"h","x":"RAY GIBBONS’ JUNGGESELLENBUDE","sz":16.0,"box":[78.8,68.9,218.2,101.9],"p":251,"i":0,"skip":true,"sec":"ray-gibbons-junggesellenbude"},{"t":"ro","x":"Ihr drückt leicht gegen die Tür, und sie öffnet sich und gibt den Blick auf eine heruntergekommene Einliegerwohnung frei, die nach fettigem Essen und schmutziger Wäsche riecht. Es sieht so aus, als würde hier jemand schon eine Weile leben, entweder in Gefangenschaft oder in Einsamkeit. Bücher, Comics und Computerspielhüllen liegen im Wohnzimmer herum, zusammen mit Socken und Schokoriegel-Verpackungen. In diesem Moment hört man eine Toilettenspülung, und ein großer, schlaksiger Junge in Shorts kommt aus dem Bad, schnappt sich geistesabwesend eine Müslipackung vom Tresen und greift nach einer Handvoll knuspriger Flocken. Dieser Slacker ist auf keinen Fall Beaumonts Superwaffe. Auf gar keinen Fall.","sz":9.0,"box":[62.4,104.3,283.8,296.9],"p":251,"i":1,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"In einer schäbigen Einliegerwohnung am Miller’s Square lebt <b>Ray Gibbons</b>, der erwachende Riss Merlins, des größten Zauberers aller Zeiten. Ray ist ein naiver 19-Jähriger und weiß nichts von der riesigen Subkultur der Risse, ist aber in den Händen Beaumonts, Eriksons oder des Teams eine potenzielle Superwaffe. (Du kannst seinen Mythos durch jede mächtige Legende ersetzen, die zu deiner Kampagne passt.) Seine Mutter Céline Rowland, der Riss der Herrin vom See, hat ihn hier versteckt.","sz":9.5,"box":[53.9,305.9,281.9,427.9],"p":251,"i":2,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"Beaumont und/oder das Team könnten nach den Ereignissen am <u>Steinaltar</u> von diesem Ort erfahren, und Céline Rowland hat schon immer davon gewusst, denn sie versteckt Ray ja hier. Die SC können den Schauplatz finden, indem sie mit anderen Methoden nach Beaumonts Superwaffe suchen, z. B. durch Wahrsagerei oder ihr Netzwerk von Riss-Informant:innen.","sz":9.5,"box":[53.9,436.5,283.8,521.0],"p":251,"i":3,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"Dort angekommen, müssen sich die SC einer Fülle von Herausforderungen stellen:","sz":9.5,"box":[53.9,529.7,282.9,551.7],"p":251,"i":4,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"• <b>Ray Gibbons</b> (Merlin) ist ein eingeschüchterter, erwachender Riss, der vor jeder unerwünschten Aufmerksamkeit zu fliehen versucht, vor allem, wenn es sich um jemanden handelt, der will, dass er von seinem Sofa aufsteht und arbeitet. Der schlaksige junge Typ im Jogginganzug und mit Mütze sieht nicht gerade wie eine Superwaffe aus. Seine wahren Kräfte wird er erst entfesseln, wenn er es nach Albion schafft, wo der Nebel schwächer ist.","sz":9.5,"box":[53.9,563.2,283.0,672.7],"p":251,"i":5,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"• Wenn die SC sich nicht die Mühe gemacht haben, Beaumont und seinem Spion Mister Barlow den Aufenthaltsort von Ray Gibbons zu verheimlichen, wird <b>Beaumont</b> in Kürze hier sein. Wenn das Team ihn besiegt hat, wird er mit Verstärkung kommen. Beaumont will Ray überzeugen, dass seine Zukunft an seiner Seite ist, indem er ihre <i>Mythos-Verbin-</i>","sz":9.5,"box":[53.9,681.4,277.6,765.9],"p":251,"i":6,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"<i>dung</i> ausnutzt, als <i>Vaterfigur</i> auftritt und ihn so mit <t>beeinflusst 3</t>, <t>beeindruckt 3</t> oder <t>inspiriert 3</t> belegt.","sz":9.5,"box":[317.5,62.5,532.9,84.5],"p":251,"i":7,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"• <b>Céline Rowland</b> (Herrin vom See), Beaumonts Mentorin und Rays Mutter, wird sich bemühen, ihren Sohn vor Beaumont und allen anderen, die seine Kräfte als Waffe einsetzen wollen, zu verstecken. Wenn die SC ihr helfen und sie überlebt, wird sie berichten, was sie über Beaumont weiß (s. S. <u>Das Geheimnis des Königs,</u> S. 237) und optional verraten, warum sie ihm geholfen hat (s. S. Die Herrin vom See, S. 199). Als sie erkannte, dass Beaumont hinter ihrem Sohn her und unheilbar verletzt war, beschloss sie, nicht mehr mit ihm zusammenzuarbeiten, und kam hierher, um ihren Sohn zu schützen.","sz":9.5,"box":[309.0,93.2,541.4,240.2],"p":251,"i":8,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"• Wie immer, wenn NSC miteinander in Konflikt geraten, kannst du das ohne Regeln erzählen oder die Regeln nutzen, um das Team zum Handeln anzuspornen, z. B. indem du Céline Rowland <t>verletzt 3</t> gibst oder indem du Beaumont versuchen lässt, Ray Gibbons’ Spektrum <i>Rekrutieren</i> auf den Maximalwert zu bringen. Denk daran, dass jeder, den Beaumont tödlich verwundet, aber nicht tötet, möglicherweise die Nimmer heilende Wunde erhält, was die Sache komplizierter macht.","sz":9.5,"box":[309.0,248.8,538.8,370.8],"p":251,"i":9,"sec":"ray-gibbons-junggesellenbude"},{"t":"h","x":"ZAUBERBANNKREIS DES LANZELOT MK II","sz":14.0,"box":[320.3,393.3,510.6,407.3],"p":251,"i":10,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"Beaumont rechnete damit, dass er sich den Zorn mächtiger Magier:innen wie eines SC, der Herrin vom See oder Merlins zuziehen könnte. Um sich vorzubereiten, ließ er die Kräfte des avalonischen Zaubers von Roxie analysieren und zapfte den Lanzelot-Mythos in dem Kriegsgolem-Relikt an. Das Ergebnis war eine Verbesserung des Modells II, die es ermöglicht, einen Kreis um sich zu erzeugen, der Magie negiert und jedem, der sich im Inneren befindet, <t>Schutz vor Magie 3</t> verleiht. Um diesen Effekt zu umgehen, muss man jeden Lanzelot-Modell II-Kriegsgolem in der Nähe ausschalten. Beaumont hält dieses Upgrade geheim, für den Fall, dass sich einige Verbündeten gegen ihn wenden.","sz":9.0,"box":[320.3,419.9,525.9,584.9],"p":251,"i":11,"sec":"ray-gibbons-junggesellenbude"}],"size":[595.276,841.89]},"252":{"tab":"","blocks":[{"t":"threat","stars":"★★","name":"RAY GIBBONS","spectra":"","items":[],"box":[132.7,58.3,153.1,70.3],"p":252,"i":0,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"Verwende das Spektrum <i>Fangen-Entkommen</i>, um die Verfolgungsjagd zu simulieren. Wenn eine der Seiten des Spektrums Stufen hat, muss die gegnerische Seite diese zuerst 1:1 entfernen, indem sie gegenläufige Zustände erzeugt. Erst dann kann man der anderen Seite des Spektrums Zustandsstufen hinzufügen. Wenn gegnerische Parteien versuchen, Ray Gibbons davon zu überzeugen, sich ihrer Sache anzuschließen, wird <i>Rekrutieren</i> ebenfalls zum Spektrum.","sz":9.0,"box":[62.4,81.4,278.2,186.4],"p":252,"i":1,"sec":"ray-gibbons-junggesellenbude"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 2 / FAN- GEN-ENTKOMMEN 3 / REKRUTIEREN 4</b>","sz":12.0,"box":[62.4,197.0,269.7,221.0],"p":252,"i":2,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"• <b>Auf der Suche nach Zugehörigkeit</b>: Solange <i>Rekrutieren</i> noch nicht das Maximum erreicht hat, ist Ray Gibbons <i>Beeinflussbar</i>. Wenn <i>Rekrutieren</i> den Maximalwert erreicht hat, ist Ray Gibbons <t>hochmütig 3</t>. • <b>Schlampige Veränderungsmagie</b>: Verringere die Stufe von Verletzen oder unschädlich machen, die Ray Gibbons erleidet, um 2, wenn er den Angriff in etwas anderes verwandeln oder einen Gegenstand in der Nähe so ändert, dass er ihn abblockt, z. B. eine Kugel in einen Schmetterling, ein Schwert in ein Stück Butter oder einen Mülleimerdeckel in einen Schutzschild. • <b>Emotionaler Schutzimpuls</b>: Einmal pro Szene, wenn ein Charakter im Begriff ist, physisch oder mystisch eine Verletzung zu erleiden, schützt Ray Gibbons ihn instinktiv und hebt den Zustand auf. • <b>Flucht durch die Gasse</b>: Wenn <i>Flucht</i> das Maximum erreicht, gelingt es Ray Gibbons, seinen Verfolgern zu entkommen (<b>Ihnen etwas verweigern, das sie wollen</b>).","sz":9.0,"box":[62.4,225.4,272.7,474.5],"p":252,"i":3,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"• Mit der angeborenen Magie eine Wand in eine Tür oder einen Müllcontainer in einen Matratzenstapel, auf dem er landen kann, verwandeln (entferne 2 Stufen von <i>Fangen</i> oder gib ihm <t>auf der Flucht 2</t>) • Seine Magie benutzen, um Hosenbeine zu verknoten oder einen Ölfleck in eine Teergrube zu verwandeln (<t>verheddert 2</t> oder <t>verlangsamt 2</t>) • Auf der Flucht Verfolger:innen anflehen, ihn in Ruhe zu lassen (<t>zögerlich 2</t>)","sz":9.0,"box":[62.4,483.4,277.5,588.4],"p":252,"i":4,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"• Einen Händedruck vortäuschen und sich dann in Richtung Feuertreppe aus dem Staub machen • Mit seiner Mütze herumfummeln, als wäre sie der spitze Hut eines Magiers","sz":9.0,"box":[62.4,597.4,268.8,642.4],"p":252,"i":5,"sec":"ray-gibbons-junggesellenbude"},{"t":"threat","stars":"★★★★","name":"CÉLINE ROWLAND","spectra":"","items":[],"box":[408.0,56.7,448.8,68.7],"p":252,"i":6,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"Die Schutz- und Täuschungskräfte, die der Mythos der Herrin des Sees verleiht, machen Céline zu einer starken Verbündeten und zu einer gefürchteten Feindin, wenn es um Hofintrigen geht, aber nicht zu einer großen Kämpferin.","sz":9.0,"box":[317.5,79.9,530.4,136.9],"p":252,"i":7,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"Um ihre umfangreichen Unterstützungsfähigkeiten darzustellen, nimm an, dass sie jede Schutz- oder Transportfähigkeit, die sie hat, auf andere ausdehnen kann, einschließlich ihrer Spezialaktionen. Wenn sich das auf Kollektive auswirkt (auch wenn es nur sie und ihr Sohn sind), reduziere den Effekt wie üblich um 1 für jeden Rang des Größenfaktors,","sz":9.0,"box":[317.5,145.9,532.0,226.9],"p":252,"i":8,"sec":"ray-gibbons-junggesellenbude"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 2 / RAY WEGZAUBERN 4</b>","sz":12.0,"box":[317.5,237.4,521.1,261.4],"p":252,"i":9,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"• <b>Nebel von Avalon</b>: Als weiche Aktion kann sie sich <t>im Nebel tarnen 4</t>, was sie vor Wahrsagern und Hellsehern verbirgt und auch legendäre Kräfte negiert. • <b>Bollwerk einer Zauberin</b>: Wenn Céline einen Zustand mit sozialer, emotionaler oder geistiger Auswirkung erlangt, egal ob weltlich oder legendär, reduziert sich dessen Stufe um 3. • <b>Außer Reichweite der Könige</b>: Wenn <i>Ray wegzaubern</i> das Maximum erreicht, transportiert Céline Rowland sich und ihn aus der Stadt. • <b>Gegenzauber</b>: Einmal pro Szene kann Céline Rowland ihre harte Aktion als Einmischung benutzen. • <b>Herrin vom See</b>: Wenn Célines Umgebung einen Marker oder Zustand der Trockenheit annimmt, behindert dies ihre magischen Fähigkeiten.","sz":9.0,"box":[317.5,265.9,532.1,442.9],"p":252,"i":10,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"• Gestikulieren und die Formeln eines Zaubers sprechen (<t>Nebel sammeln 3</t> auf <i>Ray wegzaubern</i>) • Sich selbst oder jemand auf die andere Seite der Stadt transportieren (<t>transportiert 5</t> oder <b>Ihnen etwas verweigern, was sie wollen</b>. Funktioniert nur, wenn der Zustand 5 erreicht. Danach erlischt er) • Jeden aktiven magischen Zauber, jede Fähigkeit und Gegenstand einschließlich Beaumonts <b>Avalonischen Zauber</b> bannen (verbrennt bis zu 4 Stärken oder Zustandsstufen) • Aussehen und Identität auf eine Art und Weise verändern, die nur mächtigste Magie entdecken kann (<b>Die Dinge richtig kompliziert machen</b>) • Magische Waffen aus dem Wasser beschwören (erschaffe bis zu 4 Geschichten-Marker","sz":9.0,"box":[317.5,451.9,532.2,628.9],"p":252,"i":11,"sec":"ray-gibbons-junggesellenbude"},{"t":"card","x":"wie z. B. <i>Magisches Schwert</i>, <i>Zauber parieren</i>, <i>Weltliche Rüstungen durchdringen</i>, <i>Avalonischer Stahl</i>","sz":null,"k":"yellow","box":[326.3,630.7,533.1,652.9],"p":252,"i":12,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"usw.)","sz":9.0,"box":[326.0,655.9,346.6,664.9],"p":252,"i":13,"sec":"ray-gibbons-junggesellenbude"},{"t":"p","x":"• Wasser in der Nähe plätschern und uralte Worte flüstern lassen • Mit einer sanften, hypnotischen Stimme aus den Nebeln sprechen oder singen","sz":9.0,"box":[317.5,673.9,519.7,718.9],"p":252,"i":14,"sec":"ray-gibbons-junggesellenbude"}],"size":[595.276,841.89]},"253":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 3:","sz":14.0,"box":[53.9,61.9,122.0,75.9],"p":253,"i":0,"skip":true,"sec":"schicht-3-streben-nach-macht"},{"t":"h","x":"STREBEN NACH MACHT","sz":23.0,"box":[53.9,84.2,278.6,107.2],"p":253,"i":1,"skip":true},{"t":"p","x":"Schicht 3 beginnt mit der Entdeckung eines möglichen Wendepunkts, der einer Fraktion den entscheidenden, dauerhaften Sieg bescheren könnte: Ray Gibbons (oder jeder andere SC oder NSC, der als Superwaffe fungiert). Damit beginnt ein Gerangel um die Macht über diese Person, an dem das Team, Beaumont, die Torwächter:innen und möglicherweise andere Fraktionen beteiligt sind, die die Chance ergreifen, an die Spitze der kriminellen Nahrungskette zu gelangen, wie die Adze oder Samuel Valtierra.","sz":13.0,"box":[53.9,115.1,283.4,316.6],"p":253,"i":2,"sec":"schicht-3-streben-nach-macht"},{"t":"p","x":"Schon bald gehen Ray Gibbons‘ Kräfte nach hinten los und verursachen <u>Risse allüberall.</u> Das Team muss die Macht aufgeben und anderen helfen, dasselbe zu tun, oder die Stadt steht vor der Zerstörung.","sz":9.5,"box":[53.9,327.2,281.8,374.2],"p":253,"i":3,"sec":"schicht-3-streben-nach-macht"},{"t":"h","x":"RAY GIBBONS","sz":16.0,"box":[78.0,396.5,168.7,412.5],"p":253,"i":4,"skip":true,"sec":"ray-gibbons"},{"t":"p","x":"Wie jede Superwaffe ist Ray unbeständig. Er öffnet sich seinem mächtigen Mythos zu schnell, was ihn auf einen Kollisionskurs bringt. Wie viele Ritter:innen der Tafelrunde in der Artus-Sage ist er ein <b>gefährdeter Teenager</b>: Vaterlos und im Verborgenen aufgewachsen sehnt er sich danach, in die Welt hinauszugehen und sich zu beweisen, vor allem gegenüber jemandem, der so autoritär und charismatisch ist wie Beaumont.","sz":9.5,"box":[53.9,416.4,285.6,513.4],"p":253,"i":5,"sec":"ray-gibbons"},{"t":"p","x":"Leider wollen die meisten Menschen ihn benutzen, um ihren eigenen Schmerz zu lindern: Beaumont, um seinen endlosen Krieg zu führen, die Torwächter:innen, um alle Risse im Nebel zu verbergen und seine Mutter, um ihn zu verstecken. Sogar Teammitglieder könnten in ihm nur eine Waffe sehen. <b>Der geheime Schmerz all dieser Erwachsenen kann den geheimen Schmerz Merlins als Riss definieren.</b>","sz":9.5,"box":[53.9,522.1,279.4,619.2],"p":253,"i":6,"sec":"ray-gibbons"},{"t":"p","x":"Nach seiner Ankunft in Albion potenzieren sich Rays Kräfte und verwandeln ihn in einen der mächtigsten Risse der Stadt. Seine Magie kann die Realität verändern, Menschenmassen in Insektenschwärme verwandeln oder mit einem Fingerschnippen Häuserblöcke umgestalten (und als weiche Aktion oder Einmischung Stufe-5-Zustände verursachen). Nun liegt die Macht in den Händen eines beeinflussbaren, schlecht vorbereiteten Jugendlichen.","sz":9.5,"box":[53.9,627.8,284.1,737.3],"p":253,"i":7,"sec":"ray-gibbons"},{"t":"p","x":"Jede Fraktion will Ray zur Erreichung eines anderen Ziels, was den Ort der letzten Konfrontation bestimmt:","sz":9.5,"box":[53.9,745.9,285.4,767.9],"p":253,"i":8,"sec":"ray-gibbons"},{"t":"p","x":"• <b>Beaumont will, dass Ray den König in Karmesin findet und eliminiert</b>, indem er den mächtigen Zauber (oder den Nebelschleier) zerreißt, hinter dem sich sein Feind verbirgt. Dies geschieht in einem Ringen magischer Urgewalten – der ungeformte Mythos Merlins gegen die uralte, tief verwurzelte Magie der Gralsburg – auf dem Dach eines Wolkenkratzers in der Innenstadt (der nicht der Corbin Tower ist). Sobald die Burg enthüllt ist, will Beaumont, dass Ray die Kraft des Grals aufhebt, damit er Payne töten kann, aber so weit wird er nicht kommen (s. u.)","sz":9.5,"box":[309.0,62.5,540.3,197.0],"p":253,"i":9,"sec":"ray-gibbons"},{"t":"p","x":"• <b>Die Torwächter:innen wollen, dass Ray die Enklave Albion schließt.</b> Wenn er einwilligt, wird er die Umwandlung auf dem Hügel an der Calmann- Brücke durchführen <u>(Schlacht an der Calmann-Brücke).</u> Umgekehrt könnten die Torwächter:innen Gibbons‘ destruktives Potenzial sehen und ihn selbst eliminieren oder für immer versiegeln wollen.","sz":9.5,"box":[309.0,205.7,539.9,290.2],"p":253,"i":10,"sec":"ray-gibbons"},{"t":"p","x":"• <b>Das Team könnte Ray für seine eigenen Ziele benutzen wollen.</b> Führe es mit der Macht, alles in der Stadt zu verändern und alle Feind:innen, wie Corbin Payne/dem König in Karmesin, zu beseitigen, in Versuchung. Das ist eine Möglichkeit, die die Interessen der SC mit Beaumonts in Einklang bringt.","sz":9.5,"box":[309.0,298.8,539.2,370.8],"p":253,"i":11,"sec":"ray-gibbons"},{"t":"p","x":"• <b>Manche wollen nur das Beste für Ray.</b> Wenn man ihn fragt, wiederholt er die Argumente derer, die ihn am meisten überzeugt haben. Wenn jemand hartnäckig nach Rays eigenem Wunsch fragt, gibt er kleinlaut zu, dass er gerne in seine Junggesellenbude zurückkehren und die Dinge langsam angehen würde, da er Angst vor seinen Kräften und davor, wie viel Leid sie zufügen können, hat. Dann würde er zu einem berührten Riss mit begrenzten Kräften, womit die lange Reise der Selbstentdeckung begänne.","sz":9.5,"box":[309.0,379.5,540.0,501.5],"p":253,"i":12,"sec":"ray-gibbons"},{"t":"p","x":"<b>Der Kampf um die Stadt verwandelt sich in den um Ray Gibbons und symbolisch um den eigenen Machthunger.</b> Werden die SC diesen Menschen ihrem Willen unterwerfen und ihn als Waffe nutzen oder ihre Macht aufgeben, um der Stadt Frieden zu bringen? Nichts kann den Verstand des Magiers beeinflussen, also spiel das Gespräch mit ihm als eines von Mensch zu Mensch am Rande der Massenvernichtung.","sz":9.5,"box":[309.0,510.3,539.4,607.2],"p":253,"i":13,"sec":"ray-gibbons"},{"t":"sh","x":"<b>DIE MACHT ZU ZERSTÖREN</b>","sz":10.0,"box":[309.4,620.8,459.0,630.8],"p":253,"i":14,"sec":"ray-gibbons"},{"t":"p","x":"Wer auch immer Ray davon überzeugen kann, sich auf seine Seite zu schlagen, dessen Wunsch erfüllt sich, zumindest fast. Da Rays Kräfte die Realität biegen, zerreißt der Nebel, wenn er sie einsetzt, was zu dem apokalyptischen Ereignis <u>Risse allüberall</u> führt.","sz":9.5,"box":[309.0,636.3,536.6,695.8],"p":253,"i":15,"sec":"ray-gibbons"},{"t":"p","x":"<b>Die meisten NSC werden den Zauberer bitten, es gut sein zu lassen, ehe er die Stadt zerstört. Nicht so der tief verwundete, trauernde König von Albion.</b> Als verletzter Gralsritter ist Beaumont nicht in der Lage, seinen Fehler oder Niederlage einzugeste-","sz":9.5,"box":[309.0,704.6,538.3,764.0],"p":253,"i":16,"sec":"ray-gibbons"}],"size":[595.276,841.89]},"254":{"tab":"","blocks":[{"t":"threat","stars":"★★★★★","name":"RAY GIBBONS (LEGENDE)","spectra":"","items":[],"box":[190.0,43.3,241.0,55.3],"p":254,"i":0,"sec":"ray-gibbons"},{"t":"p","x":"Merlin ist der vielleicht stärkste Magier, den die Legende kennt. Er konnte Armeen transportieren, die Steine von Stonehenge von Irland nach England versetzen, beliebige Gestalt annehmen, einen König mit Gefolge umgestalten und so weiter. Er besaß die Macht der Prophezeiung, konnte die Vergangenheit sehen und die Zukunft vorhersagen, und seine Handlungen waren durchdacht. Gleichzeitig gilt er als Abkömmling von Dämon:innen und neigte dazu, sich von romantischen Neigungen blenden zu lassen.","sz":9.0,"box":[62.4,66.4,277.4,183.4],"p":254,"i":1,"sec":"ray-gibbons"},{"t":"p","x":"Nach seiner Ankunft in Albion erlangt Ray Gibbons die Macht Merlins, aber er hat keine Zeit, die Weisheit seines magischen Mythos zu verinnerlichen. Stattdessen experimentiert er mit der neugewonnenen Macht und ist erstaunt und erschrocken über die Geheimnisse und Wunder, die sich ihm offenbaren. Emotional ist er ein beeinflussbares kleines Kind.","sz":9.0,"box":[62.4,192.4,277.7,273.4],"p":254,"i":2,"sec":"ray-gibbons"},{"t":"p","x":"Um den entfesselten Ray darzustellen, entfern seine Spezialaktionen mit Ausnahme von <b>Auf der Suche nach Zugehörigkeit</b> und füge hinzu:","sz":9.0,"box":[62.4,282.4,270.5,315.5],"p":254,"i":3,"sec":"ray-gibbons"},{"t":"p","x":"• <b>Die All-Verwandlung</b>: Die SL kann jede harte Aktion als Einmischung nutzen, um seine magischen Kräfte darzustellen. Jede Demonstration verleiht den Zustand <t>dünner Nebel 1</t> oder höher. Bei Stufe 6 verfliegt der Nebel dort – s. <u>Risse allüberall.</u>","sz":9.0,"box":[62.4,324.4,273.8,381.4],"p":254,"i":4,"sec":"ray-gibbons"},{"t":"p","x":"Da Ray Gibbons so mächtig ist und meist gegen NSC kämpft, zeigst du seine Kräfte am besten durch narrative Aktionen, wie zum Beispiel:","sz":9.0,"box":[62.4,390.1,277.2,423.1],"p":254,"i":5,"sec":"ray-gibbons"},{"t":"p","x":"• <b>Die Dinge richtig kompliziert machen</b>: Er entfernt Teile der gegnerischen Armee vom Feld. • <b>Ihnen etwas verweigern, das sie wollen</b>: Er wehrt Angriffe gegen ihn oder seine Verbündeten ab. • <b>Etwas Schreckliches geschehen lassen</b>: Er verliert die Kontrolle und tötet massenhaft Kämpfer:innen oder unschuldige Menschen, entweder direkt oder als Kollateralschaden.","sz":9.0,"box":[62.4,432.1,277.8,525.1],"p":254,"i":6,"sec":"ray-gibbons"},{"t":"p","x":"Wenn die SC einen Kampf anfangen, verwende <b>Ihnen etwas verweigern, das sie wollen</b>, um die Angriffe zu ignorieren, aber erhöhe die Stufe von <t>dünner Nebel</t>, die entsteht, wenn Gibbons es mit einer <b>Jetzt reicht’s!</b>-Aktion eines SC zu tun bekommt. Er ist in der Lage, Stufe-6-Zustände zu verursachen (hört aber bei Stufe 5 auf), bis zu 6 Stärken gleichzeitig zu verbrennen usw., z. B. jemanden einfrieren (<t>in Eis eingeschlossen 5</t>), verkleinern (<t>geschrumpft 5</t>), in magische Bande schlagen (<t>magisch gefesselt 5)</t>, alle in der Nähe blenden (<t>geblendet 5</t>) oder jemandes Relikt zerschmettern (alle Stärken verbrennen). Es gibt keine Grenze für seine Macht, aber je mehr Kraft er einsetzt, desto schneller schwindet der Nebel.","sz":9.0,"box":[62.4,533.7,276.7,698.7],"p":254,"i":7,"sec":"ray-gibbons"},{"t":"p","x":"hen und kann nur eines tun: dem König in Karmesin die Schuld geben. Seine Psychose eskaliert, und er ist überzeugt, dass die einzige Möglichkeit, die Stadt von seinem Feind zu befreien, ein verzweifelter Frontalangriff ist, selbst wenn es die Stadt vernichtet. Verlassen von seinen Fahrenden und nur in Begleitung des letzten verbliebenen Lanzelot wird er alles tun, um Ray Gibbons in der Gralsburg zu halten – und ihn so lange beschimpfen, bis die Hölle losbricht oder jemand Beaumont aufhält, indem er ihn tötet, fesselt oder in die Flucht schlägt. Ist er vorübergehend besiegt, geht er in den <u>Griffon Segréant</u> oder lässt sich dorthin bringen.","sz":9.5,"box":[309.0,59.9,541.8,206.9],"p":254,"i":8,"sec":"ray-gibbons"},{"t":"h","x":"RISSE ALLÜBERALL","sz":16.0,"box":[333.1,223.6,458.4,239.6],"p":254,"i":9,"skip":true,"sec":"risse-allueberall"},{"t":"ro","x":"Irgendetwas stimmt nicht, das spürt ihr. Ihr bemerkt eine ungewöhnliche Spannung in der Luft, zunächst kaum wahrnehmbar, wie eine Fata Morgana, aber dann immer deutlicher. Je mehr ihr darauf achtet, desto mehr scheint es, als würde etwas durch die Atmosphäre drängen, aus einer Dimension jenseits dieser Welt, von einem Ort, den ihr nicht ergründen könnt. Dann, vor euren ungläubigen Augen, zerreißt die Luft in einem Funkenregen! Eine schillernde Energie quillt aus der Wunde auf der Straße. Ein weiteres Gleißen bricht in eurem Augenwinkel aus, dann noch eines und noch eines, bis ihr auf eine Masse weit offener, funkelnder Schnitte blickt, aus denen eine Horde von Albträumen schwärmt.","sz":9.0,"box":[317.5,242.0,538.9,434.6],"p":254,"i":10,"sec":"risse-allueberall"},{"t":"p","x":"Irgendwann gibt der Nebel nach. Der Krieg zwischen Beaumont und der Stadt oder Ray Gibbons‘ mystische Macht erweisen sich als zu groß, als dass der Nebel sie verbergen könnte. Nach der <u>Schlacht an der Calmann- Brücke</u> oder wenn Ray Gibbons seine Macht entfesselt <u>(Ray Gibbons)</u> dehnt sich der Nebel zu weit, und es bilden sich Brüche. Jeder davon gehört zu einem anderen Mythos, der sich direkt manifestieren kann (als Beschwörung) oder sich in Personen, Tieren und Gegenständen in der Nähe festsetzt (Berührte).","sz":9.5,"box":[309.0,443.6,537.4,565.6],"p":254,"i":11,"sec":"risse-allueberall"},{"t":"p","x":"Überall in der Umgebung des Kriegsgebiets tauchen monströse Kreaturen und bösartige Wesen aus den neonfarbenen, leuchtenden Rissen auf und säen Chaos und Zerstörung. In dieser Szene sind mehrere Bedrohungen durch Mythen von der anderen Seite des Nebels beschrieben, aber auch jeder andere Mythos der Gewalt und des Chaos ist passend.","sz":9.5,"box":[309.0,574.3,541.1,658.8],"p":254,"i":12,"sec":"risse-allueberall"},{"t":"sh","x":"<b>DIE RISSKASKADE STOPPEN</b>","sz":10.0,"box":[309.4,672.4,463.3,682.4],"p":254,"i":13,"sec":"risse-allueberall"},{"t":"p","x":"Die Torwächter:innen sind durch den Kampf gegen das Whitecliff-Syndikat erschöpft, und es fehlt ihnen an der Nebelkraft, die nötig ist, um die Löcher im Kriegsgebiet zu schließen.","sz":9.5,"box":[309.0,687.9,540.1,734.9],"p":254,"i":14,"sec":"risse-allueberall"}],"size":[595.276,841.89]},"255":{"tab":"","blocks":[{"t":"p","x":"Als letzten Ausweg müssen sie Risse und deren Mythos-Kräfte einsetzen, um das Chaos zu bekämpfen und einzudämmen. Lars Erikson kontaktiert das Team und bittet um Hilfe.","sz":9.5,"box":[53.9,59.9,280.9,106.9],"p":255,"i":0,"sec":"risse-allueberall"},{"t":"p","x":"So sehr sie die Torwächter:innen auch hassen oder den Untergang des Nebels herbeisehnen mögen, die SC sind nun mit der drohenden Zerstörung der Stadt durch unkontrollierte Mythen des Chaos und Verderbens konfrontiert. Während sie daran arbeiten, alles einzudämmen, kämpfen sie vielleicht Seite an Seite mit Torwächter:innen-Einheiten. Weise die Spieler:innen darauf hin, dass es zumindest dieses eine Mal in jedermanns Interesse sein könnte, den Torwächter:innen zu erlauben, den Nebel zu heilen und sie zu beschützen, während sie sich sammeln.","sz":9.5,"box":[53.9,115.6,283.4,250.1],"p":255,"i":1,"sec":"risse-allueberall"},{"t":"threat","stars":"★★★","name":"BRESCHE","spectra":"","items":[],"box":[62.4,274.2,142.1,290.3],"p":255,"i":2,"sec":"risse-allueberall"},{"t":"p","x":"Eine Bresche ist ein „Loch“ im Gewebe des Nebels, in der Realität der Stadt, in Form eines leuchtenden, lokal begrenzten Spalts. Solche Lücken im Nebel nutzen Mythen aus, die mit den Umgebungsenergien in Verbindung stehen, in diesem Fall ein Mythos, der Machthunger, Gewalt und Krieg symbolisiert.","sz":9.0,"box":[62.4,297.3,273.4,366.3],"p":255,"i":3,"sec":"risse-allueberall"},{"t":"sh","x":"<b>VERSIEGELN 5 / ÜBERNEHMEN 6</b>","sz":12.0,"box":[62.4,376.8,195.2,388.8],"p":255,"i":4,"sec":"risse-allueberall"},{"t":"p","x":"• <b>Leicht zu öffnen</b>: Immer wenn ein SC in der Nähe <b>Jetzt reicht’s!</b> nutzt oder mehr als 5 Mythos-Stärken und/oder legendäre Zustandsstufen in einer einzigen Aktion nutzt, reduziert sich <i>Versiegeln</i> um 2 Stufen. Bei einem Fehlschlag reduziert es sich um 2 weitere Stufen bis zu einem Minimum von 0. • <b>Ausgeburt</b>: Wenn man den Mythos, der die Bresche bewohnt, besiegt, ist diese vorübergehend frei. Ändere die Maximalwerte ihrer Spektren auf <i>Versiegeln 2</i> und <i>Übernehmen 2</i>. Als weiche oder harte Aktion übernimmt ein neuer Mythos die Bresche (erschaffe eine neue Bedrohung). • <b>Eindringen</b>: Wenn ein SC versucht, sich in eine Bresche zu drängen, ist dies eine <b>Direkte Konfrontation</b> mit einer Kraft, die dem Mythos entspricht (Wurf+Mythos). Wenn der SC das Maximum von <i>Übernehmen</i> erreicht, verdrängt er den Mythos, und der SC übernimmt die Bresche. Die Spieler:in legt eines der Logos-Themen des SC ab und erstellt ein neues, voll entwickeltes Mythos-Thema. Avatare erhalten <t>überladen 3</t>. Setze <i>Übernehmen</i> zurück. Wenn jemand die Bresche versiegelt, <i>übernimmt</i> oder der SC sich löst, legt die Spieler:in das Mythos-Thema ab und stellt das Logos-Thema wieder her (Avatare verlieren Überladen).","sz":9.0,"box":[62.4,393.3,277.6,690.3],"p":255,"i":5,"sec":"risse-allueberall"},{"t":"p","x":"• Mythische Macht verströmen und instabil werden (2 Stufen <i>Versiegeln</i> entfernen) • Der Mythos drängt zurück (2 Stufen <i>Übernehmen</i> entfernen)","sz":9.0,"box":[62.4,699.3,269.5,744.3],"p":255,"i":6,"sec":"risse-allueberall"},{"t":"p","x":"• Mit bunter Energie schimmern und knistern","sz":9.0,"box":[62.4,753.3,246.6,762.3],"p":255,"i":7,"sec":"risse-allueberall"},{"t":"sh","x":"<b>DER ZAUBERER</b>","sz":10.0,"box":[309.4,62.8,393.6,72.8],"p":255,"i":8,"sec":"risse-allueberall"},{"t":"p","x":"Wenn Ray Gibbons noch nicht eingedämmt ist, wird nun offensichtlich, dass dies geschehen muss, da seine unkontrollierten Kräfte die Breschen verschlimmern, wenn nicht gar verursachen <u>(Ray Gibbons).</u> Wenn er mit dem Team verbündet ist, kann er seine Kräfte nicht einsetzen, um die Breschen zu kitten, die eine Folge des übermäßigen Einsatzes von Macht sind.","sz":9.5,"box":[309.0,78.3,541.3,162.8],"p":255,"i":9,"sec":"risse-allueberall"},{"t":"threat","stars":"★★★","name":"BLAUZUNGENSKINK +","spectra":"","items":[],"box":[419.0,195.6,449.6,207.6],"p":255,"i":10,"sec":"risse-allueberall"},{"t":"p","x":"Der Blauzungenskink ist ein großer Magier und Sänger aus dem Mythos der australischen Indigenen, der entweder als alter Aborigine-Mann mit strahlend weißem Bart oder als anthropomorphes blassgrünes Reptil erscheint. So machtgierig und aggressiv wie der Krieg, der ihn hierher brachte, betrog der Blauzungenskink seine eigenen Söhne um eine Mahlzeit und verbrannte sie schließlich, weil sie versehentlich sein Lieblingskänguru gejagt hatten. Diese gerissene Beschwörung wird ihre Bresche bis zum Tod verteidigen, in der Hoffnung, sich in der Stadt zu etablieren.","sz":9.0,"box":[317.5,218.7,530.0,347.7],"p":255,"i":11,"sec":"risse-allueberall"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 3 / VER- BANNEN 3 / VERBRENNEN –</b>","sz":12.0,"box":[317.6,358.2,525.0,382.2],"p":255,"i":12,"sec":"risse-allueberall"},{"t":"p","x":"• <b>Zauberei stehlen</b>: Sobald der Blauzungenskink einen Zauber oder eine Fähigkeit gesehen hat, kann er eine harte Aktion einsetzen, um ihn zu wiederholen (denselben Effekt zu erzeugen), zu konterkarieren (den Effekt aufzuheben) oder zu absorbieren (den Effekt aufzuheben und für jede Stärke oder Zustandsstufe, die er hatte, eine Stufe von <i>Verletzen oder unschädlich machen</i> oder <i>Verbannen</i> zu entfernen). <b>Zauberei stehlen</b> wirkt nicht auf magische Effekte, die mit <b>Jetzt reicht’s!</b> gewirkt werden. • <b>Jagdinstinkt</b>: Wenn er den Schauplatz betritt, ist er <t>auf Zehenspitzen 3</t>, was Versuche, ihn zu treffen oder sich anzuschleichen, verhindert. Dieser Zustand ist als harte Aktion erneuerbar.","sz":9.0,"box":[317.5,386.7,532.4,563.7],"p":255,"i":13,"sec":"risse-allueberall"},{"t":"p","x":"• Seinen Speer schleudern (<t>aufgespießt 3</t>) oder den Speer zurückholen • Jemanden dehydrieren (<t>ausgedörrt 3</t>) oder ein Gebiet austrocknen (bis zu 3 Stärken verbrennen) • eine wütende Feuersbrunst heraufbeschwören, die ein Opfer jagt (erschaffe eine neue Bedrohung: <b>Buschfeuer</b>, <i>Löschen –</i>, <i>Bannen 2</i>, <i>Verschlingen 3</i>, das Feuer kann sich als weiche Aktion <t>näher 1</t> auf <i>Verschlingen</i> geben. Wenn <i>Verschlingen</i> den Maximalwert erreicht oder wenn jemand das Feuer berührt, gibt es als weiche Aktion <t>verbrannt 4</t>). • Jemandem anbieten, Magie gegen Schutz zu lehren, (<b>Die Dinge richtig kompliziert machen</b>)","sz":9.0,"box":[317.5,572.7,532.4,725.8],"p":255,"i":14,"sec":"risse-allueberall"},{"t":"p","x":"• Ein bizarres Lied singen, während Glut und Funken ihn umwirbeln","sz":9.0,"box":[317.5,734.7,529.9,755.7],"p":255,"i":15,"sec":"risse-allueberall"}],"size":[595.276,841.89]},"256":{"tab":"","blocks":[{"t":"threat","stars":"★★","name":"CHAOSBRINGENDE DES SETH","spectra":"","items":[],"box":[207.7,328.5,228.1,340.5],"p":256,"i":0,"sec":"risse-allueberall"},{"t":"p","x":"Eine der Breschen verwandelt Unbeteiligte in berührte Krieger:innen des ägyptischen Gottes Seth, des Herrn des Chaos, der Gewalt und passenderweise der fremden Invasor:innen. Diese uralten Soldat:innen werden jede Streitmacht angreifen, die versucht, die Kontrolle über das Kriegsgebiet zu übernehmen. Sie beginnen als Kollektiv mit Größe 1 und werden mit exponentiell anwachsen, wenn niemand ihre Bresche versiegelt. Magische Adept:innen können versuchen, sie vom Einfluss des Seth zu befreien (<i>Entzaubern</i>).","sz":9.0,"box":[62.4,351.6,277.6,468.6],"p":256,"i":1,"sec":"risse-allueberall"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 3 / ENT- ZAUBERN 2</b>","sz":12.0,"box":[62.4,479.2,269.3,503.2],"p":256,"i":2,"sec":"risse-allueberall"},{"t":"p","x":"<b><i>• Was</i>-Zepter</b>: Wenn sie körperlichen Schaden erleiden, können sie mit ihrem gegabelten Zepter parieren und dessen Stufe um 2 reduzieren.","sz":9.0,"box":[62.4,507.6,264.0,540.6],"p":256,"i":3,"sec":"risse-allueberall"},{"t":"p","x":"• Jemanden mit ihrem Was-Zepter schlagen oder stechen (<t>Fleischwunde 2</t>) • Mit ihrem Zepter oder ihren bloßen Händen Dinge oder Ausrüstung zerstören (<t>beschädigt 2</t> oder bis zu 2 Stärken verbrennen) • jemandem ins Gesicht fassen und in die Augen starren, um das Opfer zu zwingen, zum <t>hirnlosen Berserker 3</t> zu werden • Zetern, wenn sich ihr Haupt in das einer Seth-Bestie verwandelt (erhöht alle Maximalwerte und Effekte der Chaosverbreiter:innen des Seth um 1)","sz":9.0,"box":[62.4,549.6,276.1,678.6],"p":256,"i":4,"sec":"risse-allueberall"},{"t":"p","x":"• Aufs Schlachtfeld stürmen und altägyptisches Kriegsgeschrei ausstoßen","sz":9.0,"box":[62.4,687.6,253.9,708.6],"p":256,"i":5,"sec":"risse-allueberall"},{"t":"threat","stars":"★★★★","name":"BAKEKUJIRA","spectra":"","items":[],"box":[383.4,329.9,424.2,341.9],"p":256,"i":6,"sec":"risse-allueberall"},{"t":"p","x":"Die Bakekujira sind japanische Geisterwale, die Dörfer heimsuchen, die Wale für Fleisch und Tran gejagt haben. Als unheimliches, schwebendes Walskelett, begleitet von seltsamen, unerkennbaren Schwärmen fliegender Fische und Vögel, verbreitet dieser gepanzerte Unglücksbomber wahllos Hunger, Pest, Feuer und Unheil, wo immer er schwebt.","sz":9.0,"box":[317.2,353.1,527.4,434.1],"p":256,"i":7,"sec":"risse-allueberall"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 6 / VER- BANNEN 2</b>","sz":12.0,"box":[317.3,444.6,524.9,468.6],"p":256,"i":8,"sec":"risse-allueberall"},{"t":"p","x":"• <b>Gigantisch</b>: Wenn ein Bakekujira einen Verletzen- oder Verbannen-Zustand erhält, reduziert sich die Stufe um 4, es sei denn, er kann den ganzen Bakekujira betreffen. • <b>Massenpanik</b>: Wenn ein Bakekujira die Szene betritt, gerät jeder, der ihn sehen kann, <t>in Panik 2</t>.","sz":9.0,"box":[317.2,473.1,530.3,542.1],"p":256,"i":9,"sec":"risse-allueberall"},{"t":"p","x":"• Ein Gebiet mit Unglück bombardieren oder einen Tsunami, Erdbeben, Feuer oder Tornado verursachen (<t>Hunger 5</t>, <t>Krankheit 5</t>, <t>Unglück 5</t>, <t>von Trümmern getroffen 5</t>, <t>ertrunken 5</t>, <t>verbrannt 5</t> usw., angepasst an den Größenfaktor, aber die Bakekujira kann keine Größen kleiner als 1 beeinflussen)","sz":9.0,"box":[317.2,551.1,525.0,632.1],"p":256,"i":10,"sec":"risse-allueberall"},{"t":"p","x":"• Die leeren Augenhöhlen auf sein Ziel richten und dann träge und langsam in die Richtung schweben • Sich winden und drehen wie ein Wal, der aus dem Wasser auftaucht • ein bizarres, grollendes Klagen ausstoßen","sz":9.0,"box":[317.2,641.1,526.9,698.1],"p":256,"i":11,"sec":"risse-allueberall"}],"size":[595.276,841.89]},"257":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 4:","sz":14.0,"box":[53.9,328.4,122.1,342.4],"p":257,"i":0,"skip":true,"sec":"schicht-4-nach-dem-krieg"},{"t":"h","x":"NACH DEM KRIEG","sz":23.0,"box":[53.9,350.7,220.1,373.7],"p":257,"i":1,"skip":true},{"t":"p","x":"Inzwischen sollten die SC erkannt haben, <b>dass Beaumont nicht gewinnen kann</b> – er ist nur ein Spielball Corbin Paynes. Beaumont ist so von Trauer zerfressen, dass der Schmerz kontrollierende König in Karmesin, sollten sie einander begegnen, ihn vollständig beherrschen wird, genau wie damals. Solange Beaumonts Schmerz ihn treibt, kann keine noch so große Macht etwas am Ausgang ändern.","sz":13.0,"box":[53.9,381.6,282.2,539.6],"p":257,"i":2,"sec":"schicht-4-nach-dem-krieg"},{"t":"p","x":"<b>Der Albion-Krieg kann nur enden, wenn man Beaumont fängt (nicht tötet), entwaffnet und heilt.</b> Andernfalls wird er zurückkehren, um den Kampf fortzusetzen und – wenn niemand das verhindert – sein Schicksal vollenden und eine vom Krieg verwüstete Stadt hinterlassen, wenn er das nicht schon getan hat.","sz":9.5,"box":[53.9,550.2,283.1,622.1],"p":257,"i":3,"sec":"schicht-4-nach-dem-krieg"},{"t":"p","x":"Wenn Beaumont den Krieg verliert – durch den Verlust Ray Gibbons‘, Albions oder beidem –, verfällt er in tiefe Depression und zieht sich zurück oder bittet das Team, ihn nach Albion oder den Überresten zurückzubringen.","sz":9.5,"box":[53.9,630.8,285.8,677.8],"p":257,"i":4,"sec":"schicht-4-nach-dem-krieg"},{"t":"p","x":"Wenn er bewusstlos oder in Gefangenschaft ist und nicht körperlich anwesend sein kann, kann im <u>Griffon Segréant</u> eine Vision seiner Psyche sein, die alle sehen können, die versuchen, ihn zu heilen oder mit ihm zu kommunizieren.","sz":9.5,"box":[53.9,686.4,282.6,745.9],"p":257,"i":5,"sec":"schicht-4-nach-dem-krieg"},{"t":"h","x":"LE GRIFFON SEGRÉANT","sz":16.0,"box":[334.8,335.3,484.8,351.3],"p":257,"i":6,"skip":true,"sec":"le-griffon-segr-ant"},{"t":"ro","x":"Warmes, flackerndes Feuerlicht begrüßt euch im Griffon Segréant, Albions beliebtester Taverne, aber es ist keine Menschenseele zu sehen. Zwischen umgestürzten Kneipentischen liegt der König von Albion zusammengesunken unter dem Tresen, hält eine Kanne Apfelwein in der Hand und summt eine traurige Melodie. Von dem einst großen, mächtigen Herrscher ist nur noch eine leere Hülle übrig. Dunkle Augenringe zeugen von seinem Kummer und verraten, dass die Obsession noch immer an seiner Seele nagt. Als ihr eintretet, hebt er verbittert sein Glas und wirft euch einen hasserfüllten Blick zu, aber angesichts des Zustands scheint er die Niederlage akzeptiert zu haben.","sz":9.0,"box":[317.5,353.7,538.9,535.5],"p":257,"i":7,"sec":"le-griffon-segr-ant"},{"t":"p","x":"In seiner zur Taverne mutierten Lieblingskneipe, dem inzwischen verfallenen Le Griffon Segréant („Zum sich aufbäumenden Greifen“), betrinkt sich Beaumont bis zum Umfallen und erzählt jedem, der zuhören will, seine Vergangenheit mit Corbin Payne.","sz":9.5,"box":[309.0,544.5,540.0,604.0],"p":257,"i":8,"sec":"le-griffon-segr-ant"},{"t":"p","x":"Wenn die Macht von Albion schwindet, sieht er wieder aus wie sein Wirt, und das erinnert das Team daran, dass er immer noch eine Geisel der Kombination aus dem Artus-Mythos und der Nimmer heilenden Wunde ist. Seine Wunde verfolgt ihn, und so sehr er es will, er kann nicht von seinem Hass auf den König in Karmesin und dem Schwur, dessen Tyrannei zu beenden, ablassen – nicht, bevor er von seinem Schmerz befreit ist, und sei es nur für einen Moment (s. u.)","sz":9.5,"box":[309.0,612.7,541.3,722.2],"p":257,"i":9,"sec":"le-griffon-segr-ant"}],"size":[595.276,841.89]},"258":{"tab":"","blocks":[{"t":"p","x":"Am Ende des Gesprächs hebt Beaumont entweder die Handgelenke, um sich Handschellen anlegen zu lassen, oder er versucht sich umzubringen, nachdem er geschworen hat, zurückzukehren.","sz":9.5,"box":[53.9,59.9,286.3,106.9],"p":258,"i":0,"sec":"le-griffon-segr-ant"},{"t":"sh","x":"<b>BEAUMONT HEILEN</b>","sz":10.0,"box":[54.3,120.5,162.3,130.5],"p":258,"i":1,"sec":"le-griffon-segr-ant"},{"t":"p","x":"Wie bei allen gescheiterten Gralsritter:innen ist Vince Beaumonts <b>Nimmer heilende Wunde</b> ein Stufe- 6-Zustand. Nur mit <b>Jetzt reicht’s!</b> kann man diesen Zustand beeinflussen: Den Wirt für eine Szene von den Auswirkungen zu befreien erfordert ein unumkehrbares Opfer, die vollständige Heilung einer solchen Wunde ein ultimatives. Optional kann ein <i>Mega!</i>-<b>Das Blatt wenden</b> den Stufe-6-Zustand für die Dauer einer Szene verringern.","sz":9.5,"box":[53.9,136.1,286.0,245.6],"p":258,"i":2,"sec":"le-griffon-segr-ant"},{"t":"p","x":"Letztlich sollte die Lösung für das Problem Vince Beaumont erzählerisch sein. Wenn ihr die Kampagne spielt, sollte die Lösung auf Corbin Payne verweisen – wenn er die Wunde verursacht hat, kann er sie vielleicht heilen. Wenn man Payne heilt, heilt das vielleicht auch Vince Beaumont und seinen Wirt usw. Wenn das Team Beaumont noch nicht heilen kann, sucht es vielleicht einen Weg, die Reinkarnation zu verhindern, vielleicht mit Hilfe Céline Rowlands, der Torwächter:innen, Ray Gibbons‘ oder Destiny Melancons.","sz":9.5,"box":[53.9,254.3,278.9,388.8],"p":258,"i":3,"sec":"le-griffon-segr-ant"},{"t":"p","x":"Wenn du Parzival verwendest, wird Beaumont Informationen preisgeben, die seiner Rolle als erster, zweiter oder dritter Gralsritter entsprechen.","sz":10.0,"box":[62.4,403.4,275.3,450.9],"p":258,"i":4,"sec":"le-griffon-segr-ant"},{"t":"card","x":"<u>ABSPANN</u>","sz":null,"k":"yellow","box":[298.1,57.3,419.0,82.4],"p":258,"i":5,"sec":"le-griffon-segr-ant"},{"t":"p","x":"• Wie sind die SC aus dem Fall hervorgegangen? Hat einer von ihnen Dinge getan oder vertreten, die er bereut? Haben sie sich an der Hinrichtung des Questentiers oder den Kämpfen zwischen den Fraktionen beteiligt? Würden sie es wieder tun oder fühlen sie sich schuldig? Was haben sie über ihr eigenes Machtstreben – und das ihrer Mitstreiter:innen – gelernt?","sz":9.5,"box":[309.0,97.7,541.2,182.2],"p":258,"i":6,"sec":"le-griffon-segr-ant"},{"t":"p","x":"• Wo ist Vince Beaumont? Sind seine Erinnerungen von Corbin Payne befreit, so dass seine Inkarnation ein freies Leben führen kann? Was ist mit den Wirten, die er dominiert hat? Erkennt jemand ihr stilles Opfer an? Wenn er nicht geheilt ist, ist er noch da draußen und wartet auf seine Reinkarnation, wenn die Stadt das nächste Mal eine Retter:in braucht?","sz":9.5,"box":[309.0,190.9,536.3,275.4],"p":258,"i":7,"sec":"le-griffon-segr-ant"},{"t":"p","x":"• Wie sieht die Stadt nach dem verheerenden Bandenkrieg aus? Behandeln die Menschen einander mit mehr Mitgefühl oder mit mehr Misstrauen? Hat die Stadt die Mittel für den Wiederaufbau, wenn die Zerstörungen großflächig sind, oder werden die Ereignisse einen wirtschaftlichen und sozialen Abschwung einleiten?","sz":9.5,"box":[309.0,284.0,534.6,368.5],"p":258,"i":8,"sec":"le-griffon-segr-ant"},{"t":"p","x":"• Wie haben die Banden den Sturm überstanden, sind sie gestärkt oder geschwächt daraus hervorgegangen? Wer wird die Lücke füllen, die der König hinterlässt? Wird ein anderer Riss mit großen Ambitionen oder gar ein Avatar einen Versuch unternehmen, sein eigenes Reich zu errichten?","sz":9.5,"box":[309.0,377.2,541.1,449.2],"p":258,"i":9,"sec":"le-griffon-segr-ant"},{"t":"p","x":"• Was ist mit dem Nebel? Wenn er verflogen war, ist er wiederhergestellt? Sehen die Torwächter:innen das Team als Verbündete, Bedrohung oder als offenes Ende? Werden sie versuchen, die Erinnerungen der SC zu löschen, oder wird Lars Erikson sie rekrutieren, um bei künftigen Ausbrüchen unappetitlicher Mythen zu helfen?","sz":9.5,"box":[309.0,457.9,538.8,542.4],"p":258,"i":10,"sec":"le-griffon-segr-ant"},{"t":"p","x":"• Ist Albion versiegelt und hat es sich in Whitecliff zurückverwandelt? Oder ist es immer noch ein Ort der Wunder inmitten einer nichtsahnenden Stadt, wenn auch nur heimlich? Hat das Verschwinden eine Lücke hinterlassen? Oder hat es sich in Schlimmeres verwandelt, in einen Friedhof der Legenden?","sz":9.5,"box":[309.0,551.0,539.7,623.0],"p":258,"i":11,"sec":"le-griffon-segr-ant"},{"t":"p","x":"• Was wurde aus Ray? Hat er die Kontrolle über seine Kräfte verloren, oder hat sich sein Wunsch erfüllt, in die Halbnormalität zurückzukehren? Wird er eine Chance bekommen, seine Kräfte in seinem Tempo zu entwickeln, oder planen längst andere Mächte, sich seiner zu bedienen? Was ist mit seiner Mutter? Was war ihr geheimes Ziel, und hat sie es erreicht?","sz":9.5,"box":[309.0,631.7,540.4,716.2],"p":258,"i":12,"sec":"le-griffon-segr-ant"}],"size":[595.276,841.89]}},"figures":[{"id":"eisberg","page":237,"kind":"eisberg","title":"Der Eisberg","file":"img/case09/eisberg.webp","box":[0,0,595,430],"after":null}],"eisberg":{"page":237,"fig":"eisberg","nodes":[{"label":"Zwischen den Fronten","layer":0,"x":41.7,"y":8.6,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Lars Erikson","layer":0,"x":56.1,"y":7.9,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Vince Beaumont","layer":0,"x":70.9,"y":7.9,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Blutbad in der Innenstadt","layer":1,"x":34.8,"y":16.5,"w":11,"h":9.5,"target":"blutbad-in-der-innenstadt"},{"label":"Die Grenzlande","layer":1,"x":48.9,"y":16.9,"w":11,"h":9.5,"target":"die-grenzlande"},{"label":"Der Steinaltar","layer":1,"x":61.7,"y":16.9,"w":11,"h":9.5,"target":"der-steinaltar"},{"label":"Camelot","layer":1,"x":74.8,"y":16.9,"w":11,"h":9.5,"target":"camelot"},{"label":"Schlacht an der Calmann-Brücke","layer":2,"x":40.9,"y":24.7,"w":11,"h":9.5,"target":"schlacht-an-der-calmann-bruecke"},{"label":"Ray Gibbons' Junggesellenbude","layer":2,"x":54.2,"y":24.7,"w":11,"h":9.5,"target":"ray-gibbons-junggesellenbude"},{"label":"Das Geheimnis des Königs","layer":2,"x":68.1,"y":24.7,"w":11,"h":9.5,"target":"das-geheimnis-des-koenigs"},{"label":"Risse allüberall","layer":3,"x":48.3,"y":32.2,"w":11,"h":9.5,"target":"risse-allueberall"},{"label":"Ray Gibbons","layer":3,"x":62.8,"y":33.0,"w":11,"h":9.5,"target":"schicht-3-streben-nach-macht"},{"label":"Le Griffon Segréant","layer":4,"x":57.2,"y":40.8,"w":11,"h":9.5,"target":"le-griffon-segr-ant"}]}};
